body.script:
/**/
        // =================================================================
        // 1. FIREBASE INITIATION & AUTH (UNIFIED & SECURE)
        // =================================================================
        import { initializeApp } from 'https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js';

        // GABUNGKAN SEMUA IMPORT FIRESTORE DI SINI AGAR TIDAK ERROR "ALREADY DECLARED"
        import { 
            getFirestore, 
            collection, 
            query, 
            orderBy, 
            limit, 
            onSnapshot, 
            addDoc, 
            deleteDoc, 
            doc, 
            updateDoc,
            setDoc, 
            serverTimestamp 
        } from 'https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js';

        import { 
            getAuth, 
            signInWithEmailAndPassword, 
            onAuthStateChanged, 
            signOut 
        } from 'https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js';

        const firebaseConfig = {
            apiKey: "AIzaSyAPNwlKmoIQRGn1PR_GAFxcyX907JfVJac",
            authDomain: "ops-cibadak02.firebaseapp.com",
            projectId: "ops-cibadak02",
            storageBucket: "ops-cibadak02.firebasestorage.app",
            messagingSenderId: "690382870933",
            appId: "1:690382870933:web:90039bc6c78da00611be9c"
        };

        const app = initializeApp(firebaseConfig);
        const db = getFirestore(app);
        const auth = getAuth(app);

        // --- TOAST (DEFINED EARLY FOR ALL MODULES) ---
        window.showToast = (msg, type = 'info') => {
            const container = document.getElementById('toast-container') || (() => {
                const c = document.createElement('div'); c.id = 'toast-container';
                document.body.appendChild(c); return c;
            })();
            const toast = document.createElement('div');
            toast.className = 'hud-toast';
            if(type === 'error') toast.style.borderColor = 'var(--hud-accent)';
            toast.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> SYSTEM_MSG: ${msg}`;
            container.appendChild(toast);
            setTimeout(() => toast.remove(), 3500);
        };
        // =================================================================
        // 2. UI TERMINAL LOG ENGINE
        // =================================================================
        function addTerminalLog(sender, text, isAlert = false) {
            const time = new Date().toLocaleTimeString('id-ID', { hour12: false });
            const entry = document.createElement('div');
            entry.className = 'comm-entry';
            const senderColor = isAlert ? 'var(--hud-accent)' : 'var(--hud-primary)';

            entry.innerHTML = `<span class='comm-time'>[${time}]</span> <span class='comm-sender' style='color:${senderColor};'>${sender}:</span><div class='comm-text'>${text}</div>`;

            const cont = document.getElementById('comm-content');
            if(cont) {
                cont.insertBefore(entry, cont.firstChild);
                if(cont.children.length > 8) cont.removeChild(cont.lastChild); // Batasi 8 log
            }
        }

        // === GLOBAL SPEAK FUNCTION (Text-to-Speech) ===
        window.speak = function(text) {
            try {
                console.log('[SPEAK] Attempting voice:', text);

                // 1. Hanya cancel jika ada yang SEDANG berbicara (speaking=true)
                // Jangan cancel pending utterances dalam queue
                if (window.speechSynthesis.speaking) {
                    console.log('[SPEAK_CANCEL_ACTIVE] Membatalkan voice aktif');
                    window.speechSynthesis.cancel();
                }

                // 2. Force resume audio context
                if (window.speechSynthesis.paused) {
                    window.speechSynthesis.resume();
                    console.log('[SPEAK_CONTEXT_RESUMED]');
                }

                // 3. Tunggu voices loaded dengan timeout safety
                const getVoicesWithTimeout = () => {
                    return new Promise((resolve) => {
                        const timeout = setTimeout(() => {
                            console.log('[SPEAK_VOICES_TIMEOUT] Using available voices');
                            resolve(window.speechSynthesis.getVoices());
                        }, 500);

                        const voices = window.speechSynthesis.getVoices();
                        if (voices.length > 0) {
                            clearTimeout(timeout);
                            resolve(voices);
                        } else {
                            window.speechSynthesis.onvoiceschanged = () => {
                                clearTimeout(timeout);
                                resolve(window.speechSynthesis.getVoices());
                            };
                        }
                    });
                };

                getVoicesWithTimeout().then(voices => {
                    console.log('[SPEAK_VOICES_AVAILABLE]', voices.length);

                    const utterance = new SpeechSynthesisUtterance(text);

                    // Cari voice
                    let selectedVoice = voices.find(v => v.lang && v.lang.startsWith('id'));
                    if (!selectedVoice) {
                        selectedVoice = voices.find(v => v.lang && v.lang.startsWith('en'));
                    }
                    if (!selectedVoice && voices.length > 0) {
                        selectedVoice = voices[0];
                    }

                    if (selectedVoice) {
                        utterance.voice = selectedVoice;
                        console.log('[SPEAK_VOICE_SELECTED]', selectedVoice.name, selectedVoice.lang);
                    }

                    utterance.lang = 'id-ID';
                    utterance.rate = 0.9;
                    utterance.pitch = 0.8;
                    utterance.volume = 1.0;

                    utterance.onerror = (e) => {
                        console.error('[SPEAK_ERROR] ❌', e.error);
                    };
                    utterance.onstart = () => {
                        console.log('[SPEAK_STARTED] 🔊 NOW PLAYING:', text.substring(0, 30));
                    };
                    utterance.onend = () => {
                        console.log('[SPEAK_END] ✅ FINISHED');
                    };
                    utterance.onpause = () => {
                        console.log('[SPEAK_PAUSED]');
                    };

                    // Queue tanpa jeda
                    window.speechSynthesis.speak(utterance);
                    console.log('[SPEAK_QUEUED]');
                });
            } catch(err) {
                console.error('[SPEAK_EXCEPTION]', err);
            }
        };

        // Log Sistem Palsu (Biar layar tetep gerak kalau forum lagi sepi/belum login)
        setInterval(() => {
            const sysMsgs = ['Dapodik sync stable.', 'Arkas connection verified.', 'Local node routing optimal.'];
            const randomMsg = sysMsgs[Math.floor(Math.random() * sysMsgs.length)];
            addTerminalLog('SYSTEM', randomMsg);
        }, 15000);


        // =================================================================
        // 3. SISTEM MONITORING FIREBASE (DIKARANTINA)
        // =================================================================
        function startMonitoring() {
            addTerminalLog('SYSTEM', 'Connecting to Warga_Node... [ONLINE]', false);

            // Pantau Postingan Baru (Threads)
            const qThreads = query(collection(db, 'threads'), orderBy('createdAt', 'desc'), limit(3));
            onSnapshot(qThreads, (snapshot) => {
                snapshot.docChanges().forEach((change) => {
                    if (change.type === "added") {
                        const data = change.doc.data();
                        addTerminalLog('WARGA_NODE', `Update: "${data.title}" by ${data.authorName}`);
                    }
                });
            }, (error) => {
                if(error.code === 'permission-denied') {
                    addTerminalLog('SECURITY', 'Access Denied: Connection lost. Re-Auth required.', true);
                } else {
                    console.error("Firestore Error:", error.message);
                }
            });

            // Pantau Laporan Pelanggaran (Reports)
            const qReports = query(collection(db, 'reports'), orderBy('createdAt', 'desc'), limit(1));
            onSnapshot(qReports, (snapshot) => {
                snapshot.docChanges().forEach((change) => {
                    if (change.type === "added") {
                        addTerminalLog('SECURITY_ALERT', `Violation report detected! Awaiting admin review.`, true);
                    }
                });
            });
        }

        // =================================================================
        // 4. LOGIKA LOGIN: DOUBLE GATE SECURITY (FIREBASE AUTH)
        // =================================================================
        const loginBtn = document.getElementById('btn-admin-auth');
        const logoutBtn = document.getElementById('btn-admin-logout');
        const loginForm = document.getElementById('login-form');
        const emailInput = document.getElementById('admin-email');
        const passwordInput = document.getElementById('admin-password');

        // === TRACKING LOGIN STATE GLOBAL ===
        window.isOpsLoggedIn = false;

        onAuthStateChanged(auth, (user) => {
            if (user) {
                // GATE 1: USER TERVERIFIKASI (LOGIN BERHASIL)
                console.log("Operator Identified:", user.email);
                window.isOpsLoggedIn = true; // ✅ ENABLE SPMB ADMIN ACCESS

                if (loginBtn) {
                    const operatorName = user.email.split('@')[0].toUpperCase();
                    loginBtn.innerHTML = `<i class='fa-solid fa-check-double'></i> NODE_SECURED: ${operatorName}`;
                    loginBtn.style.color = "var(--hud-success)";
                    loginBtn.style.borderColor = "var(--hud-success)";
                    loginBtn.style.pointerEvents = "none"; 
                }

                if (loginForm) loginForm.style.display = "none";
                if (logoutBtn) logoutBtn.style.display = "block";

                // NYALAKAN ALIRAN DATA CLOUD
                if (typeof startMonitoring === 'function') startMonitoring(); 
                if (typeof window.syncMissionsFromCloud === 'function') window.syncMissionsFromCloud();
                if (typeof window.listenToVault === 'function') window.listenToVault();

                if(typeof window.showToast === 'function') window.showToast("DATABASE_UPLINK_ESTABLISHED");
                if(typeof window.playTacSound === 'function') window.playTacSound('access');
            } else {
                // USER KELUAR / BELUM LOGIN (SISTEM SIAGA)
                console.log("System Locked: Clearance Required.");
                window.isOpsLoggedIn = false; // ❌ DISABLE SPMB ADMIN ACCESS

                if (loginBtn) {
                    loginBtn.innerHTML = "<i class='fa-solid fa-unlock-keyhole'></i> INITIATE ADMIN PROTOCOL";
                    loginBtn.style.color = "var(--hud-warning)";
                    loginBtn.style.borderColor = "var(--hud-warning)";
                    loginBtn.style.pointerEvents = "auto";
                }

                if (logoutBtn) logoutBtn.style.display = "none";

                // --- WIPE DATA (PENTING!) ---
                // Kosongkan list di layar supaya data gak nyangkut pas logout
                const listV = document.getElementById('vault-dynamic-list');
                const listM = document.getElementById('deadline-list');
                if(listV) listV.innerHTML = "<div style='color:var(--hud-accent); text-align:center; padding:20px;'>[!] ACCESS_DENIED: AUTH_REQUIRED</div>";
                if(listM) listM.innerHTML = "<div style='color:var(--hud-accent); text-align:center; padding:10px;'>ENCRYPTED_STREAM</div>";

                // Hapus data dari memori variabel
                window.vData = [];
            }
        });

        // Event Klik Tombol Login/Initiate
        if (loginBtn) {
            loginBtn.onclick = () => {
                if (loginForm.style.display === "none") {
                    loginForm.style.display = "flex";
                    loginBtn.innerHTML = "<i class='fa-solid fa-satellite-dish'></i> AUTHENTICATE";
                    emailInput.focus();
                    if(window.playTacSound) window.playTacSound('click');
                } else {
                    const email = emailInput.value.trim();
                    const password = passwordInput.value.trim();

                    if (!email || !password) {
                        window.showToast("CREDENTIALS REQUIRED", "error");
                        return;
                    }

                    loginBtn.innerHTML = "<i class='fa-solid fa-satellite-dish fa-spin'></i> VERIFYING...";

                    signInWithEmailAndPassword(auth, email, password)
                        .then((userCredential) => {
                            window.showToast("ACCESS GRANTED. UPLINK ACTIVE.");
                            addTerminalLog('SECURITY', `Operator Verified: ${userCredential.user.email}`);

                            emailInput.value = "";
                            passwordInput.value = "";

                            setTimeout(() => {
                                if(document.getElementById('folderModal')) 
                                    document.getElementById('folderModal').style.display = 'none'; 
                            }, 1000);
                        })
                        .catch((error) => {
                            window.showToast("ACCESS DENIED: INVALID KEY", "error");
                            if(window.playTacSound) window.playTacSound('error');
                            addTerminalLog('ERROR', 'Auth Failed: Unauthorized Attempt', true);

                            loginBtn.innerHTML = "<i class='fa-solid fa-triangle-exclamation'></i> AUTH FAILED";
                            loginBtn.style.color = "#ff003c";

                            setTimeout(() => {
                                loginBtn.innerHTML = "<i class='fa-solid fa-satellite-dish'></i> AUTHENTICATE";
                                loginBtn.style.color = "var(--hud-warning)";
                            }, 2000);
                        });
                }
            };
        }

        // Event Klik Tombol Logout
        if (logoutBtn) {
            logoutBtn.onclick = () => {
                if(confirm("TERMINATE OPERATOR SESSION?")) {
                    signOut(auth).then(() => {
                        window.showToast("SESSION TERMINATED", "info");
                        addTerminalLog('SYSTEM', 'Admin Session Terminated. All data wiped.', true);
                        if(window.playTacSound) window.playTacSound('error');
                    });
                }
            };
        }


        // =================================================================
        // 5. DATA MODUL OPERATOR SEKOLAH & UI LAINNYA
        // =================================================================
        const tacticalData = {
            'DAPODIK': {
                title: "ACCESS: DAPODIK SYSTEM",
                icon: "fa-solid fa-server",
                info: "<div><span class='label'>SYSTEM:</span> <span class='value'>DATA POKOK PENDIDIKAN</span></div><div><span class='label'>VERSION:</span> <span class='value'>2024.C</span></div><div><span class='label'>STATUS:</span> <span class='value'>OPERATIONAL</span></div>"
            },
            'VERVAL_PD': {
                title: "ACCESS: VERVAL PD",
                icon: "fa-solid fa-user-graduate",
                info: "<div><span class='label'>SYSTEM:</span> <span class='value'>VERVAL PESERTA DIDIK</span></div><div><span class='label'>NISN:</span> <span class='value'>SYNCED</span></div><div><span class='label'>STATUS:</span> <span class='value'>ACTIVE</span></div>"
            },
            'VERVAL_PTK': {
                title: "ACCESS: VERVAL PTK",
                icon: "fa-solid fa-chalkboard-user",
                info: "<div><span class='label'>SYSTEM:</span> <span class='value'>VERVAL PENDIDIK & TENAGA</span></div><div><span class='label'>NUPTK:</span> <span class='value'>VALIDATED</span></div><div><span class='label'>STATUS:</span> <span class='value'>ACTIVE</span></div>"
            },
            'ARKAS': {
                title: "ACCESS: ARKAS",
                icon: "fa-solid fa-file-invoice-dollar",
                info: "<div><span class='label'>SYSTEM:</span> <span class='value'>SISTEM INFORMASI BOS</span></div><div><span class='label'>TAHUN:</span> <span class='value'>2024</span></div><div><span class='label'>STATUS:</span> <span class='value'>APPROVED</span></div>"
            },
            'INFO_GTK': {
                title: "ACCESS: INFO GTK",
                icon: "fa-solid fa-file-contract",
                info: "<div><span class='label'>SYSTEM:</span> <span class='value'>VALIDASI TUNJANGAN GURU</span></div><div><span class='label'>SYNC:</span> <span class='value'>REALTIME</span></div><div><span class='label'>STATUS:</span> <span class='value'>SECURED</span></div>"
            },
            'SDM_DATA': {
                title: "ACCESS: SDM PUSDATIN",
                icon: "fa-solid fa-id-card-clip",
                info: "<div><span class='label'>SYSTEM:</span> <span class='value'>JARINGAN PENGELOLA DATA</span></div><div><span class='label'>ACCESS:</span> <span class='value'>LEVEL ADMIN</span></div><div><span class='label'>STATUS:</span> <span class='value'>VERIFIED</span></div>"
            }
        };

        // --- CUSTOM CURSOR ---
        const cursor = document.getElementById('targeting-cursor');
        let mouseX = 0, mouseY = 0, cursorX = 0, cursorY = 0;
        document.addEventListener('mousemove', (e) => { mouseX = e.clientX; mouseY = e.clientY; });
        function animateCursor() {
            cursorX += (mouseX - cursorX) * 0.2;
            cursorY += (mouseY - cursorY) * 0.2;
            if (cursor) { cursor.style.left = cursorX + 'px'; cursor.style.top = cursorY + 'px'; }
            requestAnimationFrame(animateCursor);
        }
        animateCursor();
        document.querySelectorAll('a, button, .folder-access').forEach(el => {
            el.addEventListener('mouseenter', () => cursor && cursor.classList.add('locked'));
            el.addEventListener('mouseleave', () => cursor && cursor.classList.remove('locked'));
        });

        // --- CLOCK & UPTIME ---
        let uptimeSeconds = 0;
        setInterval(() => {
            const now = new Date();
            const clockEl = document.getElementById('tactical-clock');
            if(clockEl) clockEl.textContent = now.toLocaleTimeString('id-ID', { hour12: false });

            uptimeSeconds++;
            const h = String(Math.floor(uptimeSeconds / 3600)).padStart(2, '0');
            const m = String(Math.floor((uptimeSeconds % 3600) / 60)).padStart(2, '0');
            const s = String(uptimeSeconds % 60).padStart(2, '0');
            const uptimeEl = document.getElementById('uptime');
            if(uptimeEl) uptimeEl.textContent = h + ":" + m + ":" + s;
        }, 1000);

        // =================================================================
        // MODAL CONTROLS & BIOMETRIC SCANNER (SMOOTH VOICE VERSION)
        // =================================================================
        document.querySelectorAll('.tactical-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.preventDefault();

                const btnUrl = btn.getAttribute('href');
                const btnType = btn.getAttribute('data-type');
                const data = tacticalData[btnType];
                const scanOverlay = document.getElementById('scan-overlay');

                if (data) {
                    // 1. Munculkan Scanner & Suara Akses
                    if(window.playTacSound) window.playTacSound('access');
                    if(scanOverlay) {
                        scanOverlay.style.display = 'flex';
                        scanOverlay.style.opacity = '1';
                    }

                    // 2. Kalimat Scan diperpendek agar cepat selesai
                    window.speak('Verifikasi biometrik.'); 

                    // 3. Durasi Jeda ditambah sedikit (dari 1.8s ke 2.5s) agar suara pertama kelar dulu
                    setTimeout(() => {
                        // Tutup Scanner
                        if(scanOverlay) scanOverlay.style.display = 'none';

                        // Masukkan data kembali ke Modal
                        // EFEK DECRYPTION SCRAMBLE
                        const titleEl = document.getElementById('modal-title');
                        const finalTitle = '[ ' + data.title + ' ]';
                        const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&*";
                        let iterations = 0;

                        const scramble = setInterval(() => {
                            titleEl.textContent = finalTitle.split("").map((char, index) => {
                                if(index < iterations) return finalTitle[index];
                                return chars[Math.floor(Math.random() * chars.length)];
                            }).join("");

                            if(iterations >= finalTitle.length) clearInterval(scramble);
                            iterations += 1/3; // Kecepatan efek scramble
                        }, 30);

                        // Masukkan data sisanya
                        document.getElementById('modal-icon').innerHTML = '<i class="' + data.icon + '"></i>';
                        document.getElementById('modal-info').innerHTML = data.info;
                        document.getElementById('modal-link').setAttribute('href', btnUrl);
                        document.getElementById('modal-icon').innerHTML = '<i class="' + data.icon + '"></i>';
                        document.getElementById('modal-info').innerHTML = data.info;
                        document.getElementById('modal-link').setAttribute('href', btnUrl);

                        // 4. Munculkan Modal Taktis
                        document.getElementById('tacticalModal').style.display = 'flex';

                        // 5. Suara konfirmasi akses (Jeda sedikit agar tidak memotong suara pertama)
                        setTimeout(() => {
                            window.speak(`Akses ${btnType.replace('_', ' ')} diizinkan.`);
                        }, 200);

                        addTerminalLog('SECURITY', `Access granted: ${btnType}`, false);
                    }, 2500); // <-- Durasi ditambah jadi 2.5 detik
                }
            });
        });

        window.closeModal = () => document.getElementById('tacticalModal').style.display = 'none';

        // FOLDER MODAL CONTROLS
        window.openAppFolder = () => document.getElementById('folderModal').style.display = 'flex';
        window.closeAppFolder = () => document.getElementById('folderModal').style.display = 'none';

        // Close when clicking outside modal
        window.onclick = function(event) {
            const modal1 = document.getElementById('tacticalModal');
            const modal2 = document.getElementById('folderModal');
            // vaultModal sengaja tidak dimasukkan sini supaya tidak gampang ketutup

            if (event.target == modal1) closeModal();
            if (event.target == modal2) closeAppFolder();
        };

        // --- WARNING & BOOT SEQUENCE ---
        window.dismissWarning = () => {
            const w = document.getElementById('warning-overlay');
            if(w) {
                w.style.opacity = '0';
                setTimeout(() => {
                    w.style.display = 'none';
                    if(typeof window.jarvisGreeting === 'function') {
                        window.jarvisGreeting();
                    }
                    // TAMBAHKAN TOAST DI SINI
                    window.showToast("OPERATOR_IDENTIFIED: ACCESS GRANTED");
                }, 300);
            }
        };

        // --- LOGIKA BOOT & INITIALIZATION ---
        window.addEventListener('load', () => {
            const loader = document.getElementById('boot-loader');
            const warning = document.getElementById('warning-overlay');
            const bootText = document.getElementById('boot-text');
            const bootProg = document.getElementById('boot-progress');

            // 1. CEK APAKAH SUDAH PERNAH BOOTING (SKIP LOGIC)
            if (localStorage.getItem('system_booted') === 'true') {
                loader.style.display = 'none';
                warning.style.display = 'flex';
                console.log("DASHBOARD_MODE: Boot sequence bypassed.");
                return; // Berhenti di sini
            }

            // 2. JALANKAN ANIMASI BOOTING (JIKA BELUM PERNAH)
            const steps = [
                { text: "INITIALIZING_DATA_CORE...", w: 20 },
                { text: "LOADING_LOCAL_DOMAINS...", w: 40 },
                { text: "VERIFYING_SSO_CREDENTIALS...", w: 70 },
                { text: "SYNCING_SCHOOL_DATABASE...", w: 90 },
                { text: "OPERATOR_DASHBOARD_READY", w: 100 }
            ];

            let s = 0;
            const bootInterval = setInterval(() => {
                if (s < steps.length) {
                    if(bootText) bootText.textContent = steps[s].text;
                    if(bootProg) bootProg.style.width = steps[s].w + '%';

                    // Suara bip halus setiap step (opsional)
                    if(window.playTacSound) window.playTacSound('hover');

                    s++;
                } else {
                    clearInterval(bootInterval);
                    // Munculkan tombol Enter dengan animasi kedip
                    setTimeout(() => {
                        if(bootText) {
                            bootText.innerHTML = `
                                <div style='cursor:pointer; padding:12px 25px; border:2px solid var(--hud-primary); 
                                     background: rgba(0,229,255,0.1); animation: blink 1s infinite; 
                                     font-family: "Orbitron", sans-serif; font-weight: bold; letter-spacing: 3px;' 
                                     onclick='initApp()'>
                                     <i class="fa-solid fa-power-off"></i> ENTER DASHBOARD
                                </div>`;
                        }
                    }, 500);
                }
            }, 700);
        });

        window.initApp = () => {
            const loader = document.getElementById('boot-loader');
            const warning = document.getElementById('warning-overlay');

            // Simpan status agar tidak loading lagi saat refresh
            localStorage.setItem('system_booted', 'true');

            // Play Sound Efek Masuk
            if(window.playTacSound) window.playTacSound('access');

            // Efek Transisi Pudar
            if(loader) {
                loader.style.transition = "opacity 0.8s ease, filter 0.8s ease";
                loader.style.opacity = "0";
                loader.style.filter = "blur(10px)";

                setTimeout(() => {
                    loader.style.display = 'none';
                    if(warning) {
                        warning.style.display = 'flex';
                        warning.style.opacity = '0';
                        // Fade in untuk Auth Overlay
                        setTimeout(() => { warning.style.opacity = '1'; warning.style.transition = "opacity 0.5s"; }, 50);
                    }
                }, 800);
            }
        };

        // Fungsi Tambahan: Gunakan perintah 'reboot' di terminal untuk melihat booting lagi
        window.rebootSystem = () => {
            localStorage.removeItem('system_booted');
            // GANTI alert(...) MENJADI:
            window.showToast("SYSTEM_CACHE_PURGED. REBOOTING...", "error");
            setTimeout(() => location.reload(), 1500);
        };

        // =================================================================
        // MISSION OBJECTIVES ENGINE (SINKRON KE CLOUD - FIXED CONNECT)
        // =================================================================

        // Ambil elemen dari HTML
        const taskListCont = document.getElementById('deadline-list');
        const btnOpenInput = document.getElementById('add-task-btn');
        const btnSaveToCloud = document.getElementById('save-task-btn');
        const areaInputTask = document.getElementById('task-input-area');
        const inputTaskText = document.getElementById('task-input');

        // A. Fungsi Klik Tombol "+ NEW TASK"
        if(btnOpenInput) {
            btnOpenInput.onclick = () => {
                const isHidden = areaInputTask.style.display === 'none';
                areaInputTask.style.display = isHidden ? 'flex' : 'none';
                if(isHidden) inputTaskText.focus();
            };
        }

        // B. Fungsi Klik Tombol "ADD" (Simpan ke Firebase)
        if(btnSaveToCloud) {
            btnSaveToCloud.onclick = async () => {
                const textValue = inputTaskText.value.trim();
                if (textValue !== "") {
                    try {
                        await addDoc(collection(db, "missions"), {
                            text: textValue.toUpperCase(),
                            done: false,
                            createdAt: serverTimestamp() 
                        });
                        inputTaskText.value = ""; 
                        areaInputTask.style.display = 'none'; 
                        window.showToast("MISSION UPLOADED"); 
                        if(window.playTacSound) window.playTacSound('access');
                    } catch (err) {
                        window.showToast("ERROR: LOGIN REQUIRED", "error");
                    }
                }
            };
        }

        // C. Ambil Data Realtime (Ditempel ke Window biar bisa dipanggil Saklar Utama)
        window.syncMissionsFromCloud = () => {
            if(!taskListCont) return;
            const qMissions = query(collection(db, "missions"), orderBy("createdAt", "desc"));

            onSnapshot(qMissions, (snapshot) => {
                taskListCont.innerHTML = ""; 
                if (snapshot.empty) {
                    taskListCont.innerHTML = `
                        <div class="empty-state-container">
                            <i class="fa-solid fa-shield-check empty-state-icon"></i>
                            <div class="empty-state-text">ALL MISSIONS ACCOMPLISHED</div>
                            <div class="empty-state-sub">SYSTEM SECURE // NO ACTIVE THREATS</div>
                        </div>`;
                    return;
                }
                snapshot.forEach((docSnap) => {
                    const data = docSnap.data();
                    const docId = docSnap.id;
                    const color = data.done ? 'rgba(0,229,255,0.2)' : 'var(--hud-success)';
                    const deco = data.done ? 'line-through' : 'none';
                    const textColor = data.done ? '#555' : '#fff';

                    const itemDiv = document.createElement('div');
                    itemDiv.className = 'module-item';
                    itemDiv.style.borderColor = color;
                    itemDiv.style.display = 'flex';
                    itemDiv.style.justifyContent = 'space-between';
                    itemDiv.style.alignItems = 'center';
                    itemDiv.style.padding = '10px';
                    itemDiv.innerHTML = `
                        <div style="flex: 1; cursor: pointer; display: flex; align-items: center;" onclick="window.toggleMissionStatus('${docId}', ${data.done})">
                            <span class='module-name' style="text-decoration:${deco}; color:${textColor}">${data.text}</span>
                        </div>
                        <div style="display: flex; align-items: center; gap: 15px;">
                            ${data.done ? '<i class="fa-solid fa-check" style="color:var(--hud-primary);"></i>' : '<span style="color:var(--hud-accent); font-size:0.6rem;">PENDING</span>'}
                            <i class="fa-solid fa-xmark" onclick="window.terminateMission('${docId}')" style="color:var(--hud-accent); cursor:pointer; opacity:0.5; padding:5px;"></i>
                        </div>
                    `;
                    taskListCont.appendChild(itemDiv);
                });
            });
        };

        // D. Fungsi Update status (Coret)
        window.toggleMissionStatus = async (id, currentDone) => {
            try {
                await updateDoc(doc(db, "missions", id), { done: !currentDone });
                if(window.playTacSound) window.playTacSound('click');
            } catch(e) { window.showToast("AUTH REQUIRED", "error"); }
        };

        // E. Fungsi Hapus (Terminasi)
        window.terminateMission = async (id) => {
            if(confirm("TERMINATE MISSION?")) {
                try {
                    await deleteDoc(doc(db, "missions", id));
                    if(window.playTacSound) window.playTacSound('error');
                } catch(e) { window.showToast("AUTH REQUIRED", "error"); }
            }
        };

        // PENTING: Panggil mesin biar standby
        window.syncMissionsFromCloud();

        // --- FUNGSI COPY NPSN ---
        window.copyNPSN = () => {
            const npsn = "20202659";
            navigator.clipboard.writeText(npsn).then(() => {
                // GANTI ALERT JADI TOAST
                window.showToast("NPSN COPIED TO CLIPS");
                if(typeof window.speak === 'function') window.speak('N P S N berhasil disalin.');

                // Efek visual pada teks NPSN
                const el = document.querySelector('.tactical-id');
                el.style.textShadow = "0 0 20px var(--hud-primary)";
                setTimeout(() => el.style.textShadow = "none", 500);
            });
        };

        // --- NOTES (migrated to Smart Notes v4.1) ---

        // --- SOUND ENGINE ---
        const sounds = {
            hover: new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3'),
            click: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3'),
            error: new Audio('https://assets.mixkit.co/active_storage/sfx/2573/2573-preview.mp3'),
            access: new Audio('https://assets.mixkit.co/active_storage/sfx/2569/2569-preview.mp3'),
            type: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3') // Suara tik pendek
        };
        sounds.hover.volume = 0.2;
        sounds.click.volume = 0.5;

        window.playTacSound = (type) => {
            try {
                if(sounds[type] && sounds[type].readyState >= 2) {
                    sounds[type].currentTime = 0;
                    sounds[type].play().catch(e => {});
                }
            } catch (err) {}
        };

        // Fungsi khusus untuk ngetik agar suaranya bisa tumpang tindih
        window.playTypeSound = () => {
            let t = sounds.type.cloneNode();
            t.volume = 0.05; // Suara pelan tapi berasa
            t.play().catch(()=>{});
        };

        // Pasang suara ke input terminal & notepad
        document.getElementById('terminal-input')?.addEventListener('input', playTypeSound);
        document.getElementById('note-input')?.addEventListener('input', playTypeSound);

        document.querySelectorAll('a, button, .tactical-btn, .folder-access').forEach(el => {
            el.addEventListener('mouseenter', () => playTacSound('hover'));
            el.addEventListener('click', () => playTacSound('click'));
        });

        // --- MUSICS ---
        const musicPanel = document.getElementById('music-panel');
        const musicContent = document.getElementById('music-content');
        const restoreBtn = document.getElementById('restore-music');

        document.getElementById('min-music').addEventListener('click', () => {
            musicContent.style.display = musicContent.style.display === 'none' ? 'block' : 'none';
            musicPanel.style.width = musicContent.style.display === 'none' ? '150px' : '320px';
        });

        document.getElementById('hide-music').addEventListener('click', () => {
            musicPanel.style.display = 'none';
            restoreBtn.style.display = 'block';
        });

        restoreBtn.addEventListener('click', () => {
            musicPanel.style.display = 'block';
            restoreBtn.style.display = 'none';
        });

        // --- SHORTCUT ---
        document.addEventListener('keydown', (e) => {
            // ALT + T untuk fokus ke Terminal
            if (e.altKey && e.key === 't') {
                e.preventDefault();
                const ti = document.getElementById('terminal-input');
                if(ti) ti.focus();
                if(window.playTacSound) playTacSound('click');
            }
            // ALT + N untuk ke Notepad
            if (e.altKey && e.key === 'n') {
                e.preventDefault();
                const ni = document.getElementById('note-input');
                if(ni) ni.focus();
            }
            // ESC untuk tutup semua Modal
            if (e.key === 'Escape') {
                if(typeof window.closeModal === 'function') window.closeModal();
                if(typeof window.closeAppFolder === 'function') window.closeAppFolder();
            }
        });

        // --- TOAST (moved to line ~1700 for early availability) ---

        // --- VAULT ENGINE (FIXED NULL CHECK) ---
        window.openVault = () => {
            const vModal = document.getElementById('vaultModal');
            if (vModal) {
                vModal.style.display = 'flex';
                // Timer 30 detik DIHAPUS supaya gak nutup sendiri
            } else {
                console.error("ID vaultModal tidak ditemukan!");
            }
        };

        window.closeVault = () => {
            const vModal = document.getElementById('vaultModal');
            if (vModal) vModal.style.display = 'none';
        };

        window.copyVault = (text) => {
            if (text) {
                navigator.clipboard.writeText(text);
                window.showToast("CODE COPIED TO CLIPS");
                if(window.playTacSound) window.playTacSound('click');
            }
        };

        // =================================================================
        // ENVIRONMENTAL SENSORS (WITH SMART FALLBACK)
        // =================================================================
        async function fetchWeather() {
            const tempEl = document.getElementById('weather-temp');
            const descEl = document.getElementById('weather-desc');

            try {
                const res = await fetch('https://api.open-meteo.com/v1/forecast?latitude=-6.8874&longitude=106.7792&current=temperature_2m,weather_code');
                if (!res.ok) throw new Error("Terblokir CORS/Network");

                const data = await res.json();
                const temp = data.current.temperature_2m;
                const code = data.current.weather_code;

                let desc = "CLEAR / OPTIMAL";
                if(code >= 1 && code <= 3) desc = "CLOUDY / STABLE";
                if(code >= 51 && code <= 65) desc = "RAINING / SENSOR INTERFERENCE";
                if(code >= 71) desc = "EXTREME CONDITIONS";

                tempEl.textContent = Math.round(temp) + "°C";
                descEl.innerHTML = `<i class="fa-solid fa-satellite"></i> ${desc}`;
                tempEl.style.color = "var(--hud-primary)";

            } catch(e) {
                // FALLBACK JIKA OFFLINE / ERR
                const dummyTemp = Math.floor(Math.random() * (29 - 24 + 1)) + 24; // Angka acak 24-29
                tempEl.textContent = dummyTemp + "°C";
                tempEl.style.color = "var(--hud-warning)"; // Warna amber jika simulasi
                descEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> OFFLINE_SIMULATION`;
            }
        }
        setTimeout(fetchWeather, 2000);
        setInterval(fetchWeather, 600000);

        // =================================================================
        // POWER CORE SYSTEM (REAL BATTERY TRACKER)
        // =================================================================
        if ('getBattery' in navigator) {
            navigator.getBattery().then(battery => {
                function updateBatteryInfo() {
                    // 1. Ambil Persentase
                    const level = Math.round(battery.level * 100);
                    const batteryEl = document.getElementById('cpu-val');

                    if(batteryEl) {
                        batteryEl.textContent = level + "%";

                        // 2. Berikan warna kritis jika baterai lemah
                        if (level <= 20) {
                            batteryEl.style.color = "var(--hud-accent)"; // Merah
                            addTerminalLog('POWER', 'Warning: Energy core critical!', true);
                        } else {
                            batteryEl.style.color = "var(--hud-success)"; // Hijau/Cyan
                        }
                    }

                    // 3. Status Charging (Opsional di Terminal)
                    if(battery.charging) {
                        addTerminalLog('SYSTEM', 'Power source detected. Charging core...');
                    }
                }

                // Jalankan saat pertama kali load
                updateBatteryInfo();

                // Update otomatis jika persentase berubah atau kabel dicolok
                battery.addEventListener('levelchange', updateBatteryInfo);
                battery.addEventListener('chargingchange', updateBatteryInfo);
            });
        } else {
            // Jika browser tidak mendukung (seperti beberapa versi Safari)
            document.getElementById('cpu-val').textContent = "OFFLINE";
        }

        // =================================================================
        // JARVIS INTELLIGENT GREETING SYSTEM (WITH BRIEFING PROTOCOL)
        // =================================================================
        window.jarvisGreeting = () => {
            const hour = new Date().getHours();
            let message = "";
            const name = "Pak Anggi"; 

            if (hour >= 5 && hour < 11) {
                message = `Selamat pagi, Lead Operator ${name}. Semua sistem S D N 02 Cibadak siap dioperasikan.`;
            } else if (hour >= 11 && hour < 15) {
                message = `Selamat siang, ${name}. Koneksi server pusat terpantau stabil.`;
            } else if (hour >= 15 && hour < 18) {
                message = `Selamat sore, ${name}. Jangan lupa melakukan sinkronisasi data sebelum mengakhiri shift Anda.`;
            } else if (hour >= 18 && hour < 22) {
                message = `Selamat malam, ${name}. Dashboard dalam mode pengawasan malam aktif.`;
            } else {
                message = `Anda bekerja lembur lagi, Tuan? Keamanan data tetap terjaga, namun tubuh Anda juga butuh istirahat.`;
            }

            // --- BRIEFING PROTOCOL: LAPORAN DATA MASUK SAAT OFFLINE ---
            const lastCount = parseInt(localStorage.getItem('spmb_last_count') || '0');
            const currentTotal = parseInt(document.getElementById('spmb-stat-total')?.innerText || '0');

            let briefing = "";
            if (currentTotal > lastCount && lastCount > 0) {
                const diff = currentTotal - lastCount;
                briefing += ` Selama Bapak tidak aktif, terdapat ${diff} pendaftar baru di sistem S P M B.`;
            }

            // Tambahkan Briefing Misi & Notes
            const activeMissions = document.querySelectorAll('.module-item:not([style*="line-through"])').length;
            const urgentNotes = smartNotes.filter(n => n.tag === 'URGENT').length;

            if (activeMissions > 0) {
                briefing += ` Ada ${activeMissions} misi aktif yang menunggu penyelesaian.`;
            }
            if (urgentNotes > 0) {
                briefing += ` Dan terdapat ${urgentNotes} catatan mendesak yang perlu Bapak tinjau.`;
            }

            if (briefing) {
                message += " Oh iya Pak, laporan tambahan." + briefing;
            }

            // Jalankan suara Jarvis
            if (typeof window.speak === 'function') {
                window.speak(message);
            }

            // Catat di terminal log
            addTerminalLog('JARVIS', 'Welcome message & briefing transmitted.', false);
        };

        // =================================================================
        // JARVIS VOICE COMMAND SYSTEM
        // =================================================================
        const recognition = new (window.SpeechRecognition || window.webkitSpeechRecognition)();
        recognition.lang = 'id-ID'; // Set ke Bahasa Indonesia
        recognition.continuous = false;
        recognition.interimResults = false;

        const jarvisBtn = document.getElementById('jarvis-trigger');

        window.toggleJarvis = () => {
            try {
                recognition.start();
                jarvisBtn.classList.add('listening');
                addTerminalLog('JARVIS', 'Listening for command...', false);
                if(window.playTacSound) window.playTacSound('click');
            } catch (e) {
                recognition.stop();
            }
        };

        recognition.onresult = (event) => {
            const command = event.results[0][0].transcript.toLowerCase();
            jarvisBtn.classList.remove('listening');
            addTerminalLog('USER', `"${command}"`, false);

            // LOGIKA PERINTAH SUARA
            if (command.includes('buka warga') || command.includes('forum')) {
                window.speak('Membuka Forum Warga, Pak.');
                window.open('https://warga.sdn02cibadak.sch.id/', '_blank');
            } 
            else if (command.includes('buka dapodik')) {
                window.speak('Menghubungkan ke server Dapodik.');
                window.open('https://dapo.kemendikdasmen.go.id/', '_blank');
            }
            else if (command.includes('buka presensi') || command.includes('absen')) {
                window.speak('Membuka sistem presensi online.');
                window.open('https://presensi.sdn02cibadak.sch.id/', '_blank');
            }
            else if (command.includes('status')) {
                window.speak('Semua sistem SDN 02 Cibadak berjalan optimal.');
                addTerminalLog('JARVIS', 'System Check: 100% Operational', false);
            }
            else if (command.includes('reboot') || command.includes('ulang')) {
                window.speak('Memulai ulang sistem. Sampai jumpa Pak.');
                setTimeout(() => window.rebootSystem(), 2000);
            }
            else {
                window.speak('Maaf Pak, perintah tidak dikenali.');
                addTerminalLog('JARVIS', `Unknown command: ${command}`, true);
            }
        };

        recognition.onerror = () => {
            jarvisBtn.classList.remove('listening');
        };

        recognition.onend = () => {
            jarvisBtn.classList.remove('listening');
        };

        async function pingNodes() {
            const nodes = ['sdn02cibadak.sch.id', 'presensi.sdn02cibadak.sch.id'];
            addTerminalLog('WATCHDOG', 'Scanning internal network nodes...');

            // Karena keterbatasan CORS, kita simulasi pengecekan tapi terasa nyata
            nodes.forEach(node => {
                const status = Math.random() > 0.1 ? 'ONLINE' : 'OFFLINE'; // 90% Online simulasi
                const color = status === 'ONLINE' ? 'var(--hud-success)' : 'var(--hud-accent)';
                addTerminalLog('NODE_CHECK', `${node} is <span style="color:${color}">${status}</span>`);
            });
        }
        // Jalankan setiap 5 menit
        setInterval(pingNodes, 300000);

        // =================================================================
        // THE MATRIX RAIN EFFECT
        // =================================================================
        let matrixInterval;
        window.startMatrix = () => {
            let canvas = document.getElementById('matrix-canvas-bg');
            if(!canvas) {
                canvas = document.createElement('canvas');
                canvas.id = 'matrix-canvas-bg';
                document.body.appendChild(canvas);
            }

            canvas.style.position = 'fixed';
            canvas.style.top = '0';
            canvas.style.left = '0';
            canvas.style.width = '100%';
            canvas.style.height = '100%';
            canvas.style.zIndex = '0';
            canvas.style.pointerEvents = 'none';
            canvas.style.opacity = '0.15'; // Transparan supaya tidak ganggu UI

            const ctx = canvas.getContext('2d');
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;

            const chars = '01ｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜﾝ'.split('');
            const fontSize = 14;
            const columns = canvas.width / fontSize;
            const drops = Array.from({length: columns}).fill(1);

            matrixInterval = setInterval(() => {
                ctx.fillStyle = 'rgba(3, 8, 22, 0.05)';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.fillStyle = '#0f0';
                ctx.font = fontSize + 'px monospace';

                for (let i = 0; i < drops.length; i++) {
                    const text = chars[Math.floor(Math.random() * chars.length)];
                    ctx.fillText(text, i * fontSize, drops[i] * fontSize);
                    if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) drops[i] = 0;
                    drops[i]++;
                }
            }, 33);
        };

        window.stopMatrix = () => {
            clearInterval(matrixInterval);
            const canvas = document.getElementById('matrix-canvas-bg');
            if(canvas) canvas.remove();
        };

        // =================================================================
        // LIVE UPLINK MONITORING ENGINE (SIMPLIFIED & ROBUST)
        // =================================================================
        let myNodeId = localStorage.getItem('ops_node_id');
        if(!myNodeId) {
            myNodeId = "NODE_" + Math.random().toString(36).substring(7).toUpperCase();
            localStorage.setItem('ops_node_id', myNodeId);
        }
        const myDevice = navigator.userAgent.includes("Mobi") ? "MOBILE" : "DESKTOP";

        async function registerUplink() {
            try {
                // Register/Update diri sendiri pake setDoc (Nimpa ID yang sama)
                await setDoc(doc(db, "uplinks", myNodeId), {
                    nodeId: myNodeId,
                    device: myDevice,
                    lastSeen: serverTimestamp()
                });
            } catch (e) { console.log("Uplink Error"); }
        }

        function listenToUplinks() {
            const listEl = document.getElementById('uplink-list');
            const countEl = document.getElementById('active-count');

            // Ambil semua yang ada di collection uplinks
            onSnapshot(collection(db, "uplinks"), (snap) => {
                if(!listEl) return;
                listEl.innerHTML = "";
                let count = 0;

                snap.forEach(d => {
                    const data = d.data();
                    count++;
                    const nodeDiv = document.createElement('div');
                    nodeDiv.className = 'active-node';
                    const avatarUrl = `https://api.dicebear.com/7.x/bottts/svg?seed=${data.nodeId}&backgroundColor=b6e3f4,c0aede,d1d4f9`;
                    nodeDiv.innerHTML = `<img src="${avatarUrl}" class="node-avatar" alt="avatar"/> <span>${data.nodeId} [${data.device}]</span>`;
                    listEl.appendChild(nodeDiv);
                });
                if(countEl) countEl.innerText = `${count} NODES ACTIVE`;
            });
        }

        registerUplink();
        listenToUplinks();
        setInterval(registerUplink, 30000); // Update tiap 30 detik

        // Hapus data dari database saat tab ditutup (Bersih)
        window.addEventListener('beforeunload', () => {
            deleteDoc(doc(db, "uplinks", myNodeId));
        });

        // =================================================================
        // LIVE NETWORK TRAFFIC VISUALIZER ENGINE
        // =================================================================
        function createTrafficLine() {
            const line = document.createElement('div');
            line.className = 'data-stream-line';

            // Pengaturan Acak
            const isToRight = Math.random() > 0.5;
            const topPos = Math.random() * 100; // Posisi tinggi acak
            const width = Math.floor(Math.random() * 100) + 50; // Panjang garis 50px - 150px
            const duration = Math.random() * 3 + 2; // Kecepatan 2s - 5s
            const delay = Math.random() * 5; // Jeda munculnya

            line.style.width = width + 'px';
            line.style.top = topPos + '%';
            line.style.animation = `${isToRight ? 'moveRight' : 'moveLeft'} ${duration}s linear ${delay}s infinite`;

            // Agar tidak terlalu ramai, kita batasi jumlahnya
            const existingLines = document.querySelectorAll('.data-stream-line');
            if (existingLines.length < 15) {
                document.body.appendChild(line);
            }
        }

        // Jalankan mesin pembuat garis (Buat 10 garis awal)
        for(let i = 0; i < 10; i++) {
            createTrafficLine();
        }

        // Tambahkan fungsi ini ke terminal supaya bisa di-trigger
        window.toggleTraffic = (status) => {
            const lines = document.querySelectorAll('.data-stream-line');
            lines.forEach(l => l.style.display = status ? 'block' : 'none');
        };

        // =================================================================
        // VAULT TAB SYSTEM ENGINE (BULLETPROOF & ERROR TRACKING)
        // =================================================================

        // Tanam variabel di window agar absolut tidak hilang
        window.vData =[];       
        window.vCat = 'SCHOOL';  

        // --- 1. LISTENER DATABASE (Dengan Penangkap Error) ---
        window.listenToVault = () => {
            // Hapus orderBy sementara untuk memastikan semua data ketarik tanpa syarat
            const q = query(collection(db, "vault")); 

            onSnapshot(q, (snap) => {
                window.vData = snap.docs.map(d => ({ id: d.id, ...d.data() }));
                console.log("DATA VAULT BERHASIL DITARIK:", window.vData.length, "item."); // Cek di F12 Console
                window.filterVault(); 
            }, (error) => {
                console.error("FIREBASE ERROR:", error.message);
                window.showToast("DATABASE DITOLAK: Cek Rules Firebase!", "error");
            });
        };

        // --- 2. FUNGSI PINDAH TAB ---
        window.switchVaultTab = (c) => { 
            window.vCat = c; 

            const btnSchool = document.getElementById('tab-school');
            const btnTeacher = document.getElementById('tab-teacher');
            const tInp = document.getElementById('teacher-inputs');
            const sInp = document.getElementById('school-inputs');

            if(btnSchool && btnTeacher) {
                btnSchool.style.background = c === 'SCHOOL' ? 'rgba(255,170,0,0.2)' : 'transparent';
                btnSchool.style.borderColor = c === 'SCHOOL' ? 'var(--hud-warning)' : 'rgba(255,170,0,0.3)';
                btnTeacher.style.background = c === 'TEACHER' ? 'rgba(0,229,255,0.2)' : 'transparent';
                btnTeacher.style.borderColor = c === 'TEACHER' ? 'var(--hud-primary)' : 'rgba(0,229,255,0.3)';
            }
            if(tInp && sInp) {
                tInp.style.display = c === 'TEACHER' ? 'flex' : 'none';
                sInp.style.display = c === 'SCHOOL' ? 'block' : 'none';
            }

            if(window.playTacSound) window.playTacSound('click');
            window.filterVault(); 
        };

        // --- 3. MESIN FILTER & RENDER DATA (Anti Crash) ---
        window.filterVault = () => {
            const listV = document.getElementById('vault-dynamic-list');
            const searchInp = document.getElementById('vault-search');
            const search = searchInp ? searchInp.value.toLowerCase().trim() : "";

            if(!listV) return;
            listV.innerHTML = "";

            // Filter data Super Aman
            const filtered = window.vData.filter(i => {
                const itemCat = i.category || 'SCHOOL'; 
                const itemLabel = i.label || 'TANPA_NAMA';

                if (itemCat !== window.vCat) return false;
                if (search !== "" && !itemLabel.toLowerCase().includes(search)) return false;
                return true;
            });

            // ==========================================
            // TAMBAHAN BARU: UPDATE DROPDOWN DATALIST
            // ==========================================
            const datalist = document.getElementById('existing-labels');
            if (datalist) {
                // Ambil nama-nama unik dari data yang sudah ada di database (kategori saat ini)
                const uniqueNames =[...new Set(window.vData
                    .filter(i => (i.category || 'SCHOOL') === window.vCat)
                    .map(i => i.label)
                )];
                // Masukkan ke dalam dropdown
                datalist.innerHTML = uniqueNames.map(name => `<option value="${name}">`).join('');
            }
            // ==========================================

            if (filtered.length === 0) {
                listV.innerHTML = `<div style="text-align:center; padding:15px; color:#666; font-size:0.65rem; letter-spacing:2px;">NO_DATA_IN_[${window.vCat}]</div>`;
                return;
            }

            if (window.vCat === 'SCHOOL') {
                filtered.forEach(i => {
                    const div = document.createElement('div');
                    div.className = 'module-item';
                    div.innerHTML = `
                        <div style="flex:1;">
                            <div style="font-size:0.65rem; color:#888; font-weight:bold;">${i.label || 'UNKNOWN'}</div>
                            <div id="p-${i.id}" onclick="window.decrypt('${i.id}','${i.value}')" style="cursor:pointer; color:var(--hud-warning); font-size:0.8rem; margin-top:3px;">******** (CLICK_TO_COPY)</div>
                        </div>
                        <i class="fa-solid fa-trash" onclick="window.delV('${i.id}')" style="opacity:0.3; font-size:0.8rem; cursor:pointer; color:var(--hud-accent);"></i>`;
                    listV.appendChild(div);
                });
            } else {
                // LOGIKA FOLDER GURU (Personnel)
                const grouped = {};
                filtered.forEach(item => {
                    const tName = item.label || "GURU_TANPA_NAMA";
                    if(!grouped[tName]) grouped[tName] = [];
                    grouped[tName].push(item);
                });

                Object.keys(grouped).forEach(teacherName => {
                    const folder = document.createElement('div');
                    folder.style.cssText = "border:1px solid rgba(0, 229, 255, 0.2); margin-bottom:10px; background:rgba(0,0,0,0.3); border-radius:4px;";
                    folder.innerHTML = `
                        <div onclick="window.toggleFolder(this)" style="padding:12px; background:rgba(0,229,255,0.05); border-bottom:1px solid rgba(0, 229, 255, 0.1); cursor:pointer; display:flex; justify-content:space-between; font-weight:bold; font-size:0.75rem;">
                            <span><i class="fa-solid fa-user-tie"></i> ${teacherName}</span>
                            <i class="fa-solid fa-chevron-down"></i>
                        </div>
                        <div style="display:none; padding:10px; background:rgba(0,0,0,0.5);">
                            ${grouped[teacherName].map(acc => {
                                const parts = (acc.value || "").split(' | ');
                                const type = parts[0] || "AKUN"; 
                                const user = parts[1] || "-"; 
                                const pass = parts[2] || "-";
                                return `
                                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid rgba(255,255,255,0.05); padding:8px 0; margin-bottom:5px;">
                                    <div style="flex:1">
                                        <div style="font-size:0.55rem; color:var(--hud-success)">${type}</div>
                                        <div style="font-size:0.7rem; color:#fff; margin-top:2px;">ID: ${user}</div>
                                        <div style="font-size:0.7rem; color:var(--hud-warning); margin-top:2px;">PW: ${pass}</div>
                                    </div>
                                    <div style="display:flex; gap:12px; align-items:center;">
                                        <i class="fa-solid fa-copy" onclick="window.copyVaultPass('${acc.id}', '${pass}')" style="cursor:pointer; color:#fff; opacity:0.5;"></i>
                                        <i class="fa-brands fa-whatsapp" onclick="window.sendToWA('${teacherName}', '${type}', '${user}', '${pass}')" style="color:#25D366; cursor:pointer; font-size:1.2rem;"></i>
                                        <i class="fa-solid fa-trash" onclick="window.delV('${acc.id}')" style="color:var(--hud-accent); opacity:0.4; font-size:0.8rem; cursor:pointer"></i>
                                    </div>
                                </div>`;
                            }).join('')}
                        </div>`;
                    listV.appendChild(folder);
                });
            }
        };

        // --- 4. FUNGSI SIMPAN KE CLOUD ---
        window.saveToVault = async () => {
            const label = document.getElementById('new-vault-label').value.trim();
            let finalValue = "";

            if (window.vCat === 'SCHOOL') {
                finalValue = document.getElementById('new-vault-value-school').value.trim();
            } else {
                const typeAcc = document.getElementById('new-vault-acc-type').value;
                const manualType = document.getElementById('new-vault-manual-type').value.trim();
                const email = document.getElementById('new-vault-email').value.trim();
                const pass = document.getElementById('new-vault-pass').value.trim();

                const type = typeAcc === 'LAINNYA' ? manualType : typeAcc;
                finalValue = `${type.toUpperCase()} | ${email} | ${pass}`;
            }

            if(!label || !finalValue || finalValue === " |  | ") return window.showToast("DATA_INCOMPLETE", "error");

            try {
                window.showToast("ENCRYPTING...");
                await addDoc(collection(db, "vault"), { 
                    label: label.toUpperCase(), 
                    value: finalValue, 
                    category: window.vCat, 
                    timestamp: serverTimestamp() 
                });
                window.showToast("DATA SECURED");

                document.getElementById('new-vault-label').value = "";
                document.getElementById('new-vault-value-school').value = "";
                document.getElementById('new-vault-email').value = "";
                document.getElementById('new-vault-pass').value = "";
                document.getElementById('new-vault-manual-type').value = "";
                if(window.playTacSound) window.playTacSound('access');
            } catch(e) { window.showToast("AUTH_ERROR", "error"); }
        };

        // --- 5. HELPER FUNCTIONS ---
        window.checkOtherAcc = (el) => {
            const manualInp = document.getElementById('new-vault-manual-type');
            if(manualInp) manualInp.style.display = el.value === 'LAINNYA' ? 'block' : 'none';
        };

        window.toggleFolder = (el) => {
            const details = el.nextElementSibling;
            const icon = el.querySelector('.fa-chevron-down');
            const isOpen = details.style.display === 'block';
            details.style.display = isOpen ? 'none' : 'block';
            if(icon) icon.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
            if(window.playTacSound) window.playTacSound('click');
        };

        window.decrypt = (id, val) => {
            navigator.clipboard.writeText(val);
            const el = document.getElementById(`p-${id}`);
            if(el) {
                el.innerText = val; el.style.color = "var(--hud-success)";
                window.showToast("COPIED TO CLIPBOARD");
                setTimeout(() => { el.innerText = "******** (CLICK_TO_COPY)"; el.style.color = "var(--hud-warning)"; }, 3000);
            }
        };

        window.copyVaultPass = (id, pass) => {
            navigator.clipboard.writeText(pass);
            window.showToast("PASSWORD_COPIED");
            if(window.playTacSound) window.playTacSound('click');
        };

        window.sendToWA = (name, type, user, pass) => {
            const text = encodeURIComponent(`Halo ${name},\n\nBerikut data akun *${type}* Anda:\n📧 *User:* ${user}\n🔑 *Pass:* ${pass}\n\n_Data Ops SDN 02 Cibadak._`);
            window.open(`https://wa.me/?text=${text}`, '_blank');
        };

        window.delV = async (id) => {
            if(confirm("DELETE THIS ENCRYPTED NODE?")) {
                await deleteDoc(doc(db, "vault", id));
                if(window.playTacSound) window.playTacSound('error');
            }
        };

        // Panggil langsung mesin penarik datanya!
        window.listenToVault();

        // =================================================================
        // VAULT AUTHENTICATION SYSTEM (HUD STYLE)
        // =================================================================
        const vaultAuthInput = document.getElementById('vault-auth-input');
        const btnVerifyVault = document.getElementById('btn-verify-vault');

        // Fungsi Tutup Modal Auth
        window.closeVaultAuth = () => {
            document.getElementById('vaultAuthModal').style.display = 'none';
        };

        // Fungsi Verifikasi Key
        async function verifyVaultKey() {
            const inputKey = vaultAuthInput.value.trim();

            if (inputKey === "02") { // <--- SESUAIKAN PASSWORD DISINI
                closeVaultAuth();
                window.openVault(); // Panggil fungsi buka brankas beneran
                window.showToast("ACCESS GRANTED: VAULT UNLOCKED");
                if(window.playTacSound) window.playTacSound('access');
                window.speak('Otentikasi berhasil. Selamat datang di brankas data.');

                // Catat di Terminal History (Opsional)
                addTerminalLog('SECURITY', 'Vault accessed with Master Key.', false);
            } else {
                window.showToast("ACCESS DENIED: INVALID KEY", "error");
                if(window.playTacSound) window.playTacSound('error');
                window.speak('Akses ditolak. Kunci tidak valid.');

                // Efek getar jika salah (opsional)
                vaultAuthInput.style.borderColor = 'red';
                setTimeout(() => vaultAuthInput.style.borderColor = 'var(--hud-warning)', 500);
            }
        }

        // Jalankan verifikasi saat klik tombol atau pencet Enter
        if(btnVerifyVault) btnVerifyVault.onclick = verifyVaultKey;

        vaultAuthInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') verifyVaultKey();
        });

        // --- POWER CORE SYNC ---
        if ('getBattery' in navigator) {
            navigator.getBattery().then(battery => {
                const updateHUD = () => {
                    const level = Math.round(battery.level * 100);
                    const cpuVal = document.getElementById('cpu-val');
                    const ringCpu = document.getElementById('ring-cpu'); // Target ring

                    if(cpuVal) {
                        cpuVal.textContent = level + "%";
                        // Warna indikator: Merah kalau low, Cyan kalau aman
                        const color = level <= 20 ? 'var(--hud-accent)' : 'var(--hud-primary)';
                        cpuVal.style.color = color;

                        // Update Progress Melingkar
                        if(ringCpu) {
                            ringCpu.style.background = `conic-gradient(${color} ${level}%, transparent 0%)`;
                            if(battery.charging) {
                                ringCpu.style.boxShadow = `0 0 20px ${color}`;
                            } else {
                                ringCpu.style.boxShadow = `none`;
                            }
                        }
                    }
                };
                battery.addEventListener('levelchange', updateHUD);
                battery.addEventListener('chargingchange', updateHUD);
                updateHUD();
            });
        }

        // =================================================================
        // MERGED ENGINE: TERMINAL, NOTEPAD, & HOTKEYS (V3.1 FINAL - FIXED)
        // =================================================================

        const tInput = document.getElementById('terminal-input');
        const tHistory = document.getElementById('terminal-history');
        const tScroll = document.getElementById('term-scroll-area');
        const pad = document.getElementById('note-input') || {value:'',addEventListener:()=>{},focus:()=>{}};

        // --- FITUR 1: TERMINAL INTERAKTIF (VERSI FINAL RAPI) ---

        // Penampung riwayat perintah (History Buffer)
        let cmdHistory = [];
        let historyIndex = -1;

        async function processTerminal(cmd) {
            let response = "";
            const cleanCmd = cmd.toLowerCase().trim();

            if (cleanCmd === "") return;

            // Rangkaian Logika Perintah
            if (cleanCmd === 'help') {
                response = "COMMANDS: [DAPODIK, ARKAS, CLEAR, STATUS, NOTES, STEALTH, POWER, VAULT, SCAN, MATRIX, REBOOT]";
            } 
            else if (cleanCmd === 'clear') { 
                tHistory.innerHTML = ""; 
                return; 
            }
            else if (cleanCmd === 'stealth' || cleanCmd === 'mask') {
                const isNowActive = document.body.classList.toggle('stealth-active');
                response = isNowActive ? "STEALTH_MODE: ACTIVATED. DATA MASKED." : "STEALTH_MODE: DEACTIVATED. STANDBY.";
                if(typeof window.speak === 'function') window.speak(isNowActive ? 'Protokol senyap aktif.' : 'Sistem kembali normal.');
                setTimeout(() => tInput.focus(), 100); 
            }
            else if (cleanCmd === 'status') {
                response = "ALL NODES SECURE. ENCRYPTION AES-256 ACTIVE. NODE: SDN 02 CIBADAK.";
            }
            else if (cleanCmd === 'power') {
                if ('getBattery' in navigator) {
                    const battery = await navigator.getBattery();
                    response = `POWER_CORE: ${Math.round(battery.level * 100)}% [${battery.charging ? 'CHARGING' : 'DISCHARGING'}]`;
                } else { response = "POWER_CORE: OFFLINE."; }
            }
            else if (cleanCmd === 'vault') {
                if (!auth.currentUser) {
                    response = "ACCESS_DENIED: OPERATOR NOT IDENTIFIED. LOGIN REQUIRED.";
                    window.showToast("SECURITY ALERT: UNAUTHORIZED ACCESS", "error");
                    if(window.playTacSound) window.playTacSound('error');
                    window.speak('Akses ditolak. Identitas operator tidak ditemukan.');
                } else {
                    document.getElementById('vaultAuthModal').style.display = 'flex';
                    document.getElementById('vault-auth-input').value = '';
                    document.getElementById('vault-auth-input').focus();
                    response = "VAULT_LOCK_DETECTED: AWAITING MASTER KEY...";
                    window.speak('Brankas terdeteksi. Masukkan kunci utama.');
                }
            }
            else if (cleanCmd === 'scan' || cleanCmd === 'check health') {
                const line = document.getElementById('scanner-line');
                if(line) {
                    line.style.display = 'block';
                    line.style.animation = 'scanMoving 2s ease-in-out';
                    setTimeout(() => { line.style.display = 'none'; line.style.animation = ''; window.showToast("SYSTEM HEALTH: 100%"); }, 2000);
                }
                response = "DIAGNOSTIC_START: SCANNING_HARDWARE_INTEGRITY...";
                if(typeof window.speak === 'function') window.speak('Memulai diagnosa sistem.');
            }
            else if (cleanCmd === 'reboot') {
                response = "REBOOTING SYSTEM..."; 
                setTimeout(() => window.rebootSystem(), 1000); 
            }
            else if (cleanCmd === 'notes') {
                response = "FOCUSING NOTEPAD..."; 
                pad.focus(); 
            }
            else if (cleanCmd === 'dapodik') {
                response = "ROUTING TO DAPODIK EXTERNAL SERVER..."; 
                window.open('https://dapo.kemendikdasmen.go.id/', '_blank'); 
            }
            else if (cleanCmd === 'vault edit') {
                const form = document.getElementById('vault-admin-form');
                if(form) {
                    form.style.display = form.style.display === 'none' ? 'block' : 'none';
                    response = "VAULT_EDITOR: " + (form.style.display === 'block' ? 'ENABLED' : 'DISABLED');
                }
            }
            else if (cleanCmd === 'matrix --run' || cleanCmd === 'matrix') {
                if(typeof window.startMatrix === 'function') window.startMatrix();
                response = "VISUAL_OVERRIDE: MATRIX_STREAM_STARTED. (TYPE 'MATRIX --STOP' TO HALT)";
                if(typeof window.speak === 'function') window.speak('Memulai aliran data matriks.');
            }
            else if (cleanCmd === 'matrix --stop') {
                if(typeof window.stopMatrix === 'function') window.stopMatrix();
                response = "MATRIX_STREAM_TERMINATED. SYSTEM NORMALIZED.";
            }
            // --- FITUR: TRAFFIC VISUALIZER CONTROL ---
            else if (cleanCmd === 'traffic --off') {
                if(typeof window.toggleTraffic === 'function') window.toggleTraffic(false);
                response = "NETWORK_VISUALIZER: DISABLED.";
            }
            else if (cleanCmd === 'traffic --on') {
                if(typeof window.toggleTraffic === 'function') window.toggleTraffic(true);
                response = "NETWORK_VISUALIZER: RESTORED.";
            }
            else {
                response = "ERROR: COMMAND '" + cleanCmd.toUpperCase() + "' NOT RECOGNIZED.";
            }

            // Cetak hasil ke layar terminal (DENGAN TYPEWRITER EFFECT)
            const line = document.createElement('div');
            line.className = 'terminal-line';
            line.innerHTML = `<span class='terminal-prompt'>ops@sdn02cibadak:~$</span> <span style="color:#fff">${cmd}</span><br/><span class='terminal-res'>> <span class='type-target'></span><span class='typing-cursor'></span></span>`;
            tHistory.appendChild(line);

            const target = line.querySelector('.type-target');
            const cursorBlip = line.querySelector('.typing-cursor');
            let i = 0;

            // Matikan input saat sedang nge-print biar gak error
            tInput.disabled = true;

            function typeWriter() {
                if (i < response.length) {
                    target.innerHTML += response.charAt(i);
                    if(i % 2 === 0 && typeof playTypeSound === 'function') playTypeSound(); // Bunyi tiap 2 huruf
                    i++;
                    if(tScroll) tScroll.scrollTop = tScroll.scrollHeight;
                    setTimeout(typeWriter, 15); // Kecepatan ngetik
                } else {
                    cursorBlip.style.display = 'none'; // Sembunyikan cursor saat selesai
                    tInput.disabled = false;

                    // --- PERBAIKAN FOKUS KURSOR DI SINI ---
                    if (cleanCmd === 'vault') {
                        const pwdInput = document.getElementById('vault-auth-input');
                        if (pwdInput) pwdInput.focus();
                    } else if (cleanCmd === 'notes') {
                        const noteInput = document.getElementById('note-input');
                        if (noteInput) noteInput.focus();
                    } else {
                        tInput.focus(); // Kembalikan ke terminal untuk perintah biasa
                    }
                    // --------------------------------------
                }
            }
            typeWriter();

            if(window.playTacSound) window.playTacSound('access');
        }

        if(tInput) {
            tInput.addEventListener('keydown', (e) => {
                // 1. Eksekusi Command (Enter)
                if (e.key === 'Enter') {
                    const val = tInput.value.trim();
                    if(val) {
                        cmdHistory.push(val); // Simpan ke riwayat
                        historyIndex = cmdHistory.length; // Reset index ke paling baru
                        processTerminal(val);
                    }
                    tInput.value = '';
                } 
                // 2. Panggil Riwayat Terakhir (Panah Atas)
                else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    if (cmdHistory.length > 0) {
                        if (historyIndex > 0) historyIndex--;
                        tInput.value = cmdHistory[historyIndex];
                        // Pindahkan kursor ke paling belakang
                        setTimeout(() => tInput.setSelectionRange(tInput.value.length, tInput.value.length), 0);
                    }
                } 
                // 3. Riwayat Berikutnya (Panah Bawah)
                else if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    if (historyIndex < cmdHistory.length - 1) {
                        historyIndex++;
                        tInput.value = cmdHistory[historyIndex];
                    } else {
                        historyIndex = cmdHistory.length;
                        tInput.value = ''; // Kembali ke baris kosong
                    }
                }
            });
        }

        // --- FITUR 2: NOTEPAD migrated to Smart Notes v4.1 ---

        // --- FITUR 3: KEYBOARD SHORTCUTS (HOTKEYS) ---
        document.addEventListener('keydown', (e) => {
            // ALT + V = Vault Instan
            if (e.altKey && e.key.toLowerCase() === 'v') {
                e.preventDefault();
                processTerminal('vault');
            }
            // ALT + S = STEALTH MODE
            if (e.altKey && e.key.toLowerCase() === 's') {
                e.preventDefault();
                processTerminal('stealth');
            }
            // ALT + T = Fokus ke Terminal
            if (e.altKey && e.key.toLowerCase() === 't') {
                e.preventDefault();
                tInput.focus();
                if(window.playTacSound) window.playTacSound('click');
            }
            // ALT + N = Fokus ke Notepad
            if (e.altKey && e.key.toLowerCase() === 'n') {
                e.preventDefault();
                pad.focus();
                if(window.playTacSound) window.playTacSound('click');
            }
            // ESC = Tutup Modal
            if (e.key === 'Escape') {
                if(typeof closeModal === 'function') closeModal();
                if(typeof closeAppFolder === 'function') closeAppFolder();
                if(typeof closeVault === 'function') closeVault();
                if(typeof closeVaultAuth === 'function') closeVaultAuth();
            }
        });

        // =================================================================
        // NEW FEATURES ENGINE v4.0
        // =================================================================

        // --- THEME ENGINE ---
        window.applyTheme = (primary, success, accent, el) => {
            document.documentElement.style.setProperty('--hud-primary', primary);
            document.documentElement.style.setProperty('--hud-success', success);
            document.documentElement.style.setProperty('--hud-accent', accent);
            localStorage.setItem('theme_p', primary);
            localStorage.setItem('theme_s', success);
            localStorage.setItem('theme_a', accent);
            document.querySelectorAll('.theme-opt-card').forEach(c => c.classList.remove('active-theme'));
            if(el) el.classList.add('active-theme');
            window.showToast('THEME_UPDATED: ' + primary.toUpperCase());
            if(window.playTacSound) playTacSound('access');
        };
        (function loadSavedTheme() {
            const p=localStorage.getItem('theme_p'),s=localStorage.getItem('theme_s'),a=localStorage.getItem('theme_a');
            if(p) { document.documentElement.style.setProperty('--hud-primary',p); document.documentElement.style.setProperty('--hud-success',s); document.documentElement.style.setProperty('--hud-accent',a); }
        })();

        // --- SETTINGS ENGINE ---
        const settingsCfg = {
            sound: localStorage.getItem('cfg_sound') !== 'false',
            ruler: localStorage.getItem('cfg_ruler') === 'true',
            dyslexic: localStorage.getItem('cfg_dyslexic') === 'true',
            crt: localStorage.getItem('cfg_crt') !== 'false',
            traffic: localStorage.getItem('cfg_traffic') !== 'false',
            radar: localStorage.getItem('cfg_radar') !== 'false',
            cursor: localStorage.getItem('cfg_cursor') !== 'false'
        };
        function applyAllSettings() {
            const lines = document.querySelectorAll('.data-stream-line');
            lines.forEach(l => l.style.display = settingsCfg.traffic ? '' : 'none');
            const radar = document.querySelector('.radar-container');
            if(radar) radar.style.opacity = settingsCfg.radar ? '' : '0';
            const cur = document.getElementById('targeting-cursor');
            if(cur) cur.style.display = settingsCfg.cursor ? '' : 'none';

            // Reading Ruler & Dyslexic
            const ruler = document.getElementById('reading-ruler');
            if(ruler) ruler.style.display = settingsCfg.ruler ? 'block' : 'none';
            document.body.classList.toggle('dyslexic-font', settingsCfg.dyslexic);

            ['sound','ruler','dyslexic','crt','traffic','radar','cursor'].forEach(k => {
                const el = document.getElementById('tog-'+k);
                if(!el) return;
                settingsCfg[k] ? el.classList.add('on') : el.classList.remove('on');
                settingsCfg[k] ? el.querySelector('.s-knob').style.left = '22px' : el.querySelector('.s-knob').style.left = '2px';
            });
        }

        // Reading Ruler Mouse Follow
        document.addEventListener('mousemove', (e) => {
            if(settingsCfg.ruler) {
                const ruler = document.getElementById('reading-ruler');
                if(ruler) ruler.style.top = e.clientY + 'px';
            }
        });

        window.toggleSetting = (key) => {
            settingsCfg[key] = !settingsCfg[key];
            localStorage.setItem('cfg_'+key, settingsCfg[key]);
            applyAllSettings();
            if(settingsCfg.sound && window.playTacSound) playTacSound('click');
        };
        window.openSettings = () => { document.getElementById('settings-modal').style.display='flex'; const sv=localStorage.getItem('stat_siswa'); const gv=localStorage.getItem('stat_guru'); const rv=localStorage.getItem('stat_rombel'); if(sv){document.getElementById('cfg-siswa').value=sv;} if(gv){document.getElementById('cfg-guru').value=gv;} if(rv){document.getElementById('cfg-rombel').value=rv;} if(window.playTacSound) playTacSound('click'); };
        window.closeSettings = () => { document.getElementById('settings-modal').style.display='none'; };
        window.saveSchoolConfig = async () => { 
            const s = document.getElementById('cfg-siswa').value; 
            const g = document.getElementById('cfg-guru').value; 
            const r = document.getElementById('cfg-rombel').value; 

            // 1. Simpan di Local Storage agar tetap responsif
            if(s) localStorage.setItem('stat_siswa', s); 
            if(g) localStorage.setItem('stat_guru', g); 
            if(r) localStorage.setItem('stat_rombel', r); 

            // 2. Tembak data ke Cloud Database Firebase!
            try {
                await setDoc(doc(db, "settings", "school_stats"), {
                    siswa: s || '156',
                    guru: g || '12',
                    rombel: r || '6'
                }, { merge: true });
            } catch(e) {
                console.log("Database Sync Error: ", e);
            }

            initAnalytics(); 
            closeSettings(); 
            window.showToast('SCHOOL_CONFIG_SAVED_TO_CLOUD'); 
        };

        // 3. Mesin Pendengar Database (Jika diubah di Laptop, di HP otomatis ikut berubah Real-time)
        onSnapshot(doc(db, "settings", "school_stats"), (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();

                // Update memori lokal
                localStorage.setItem('stat_siswa', data.siswa);
                localStorage.setItem('stat_guru', data.guru);
                localStorage.setItem('stat_rombel', data.rombel);

                // Update angka di form input setting
                if(document.getElementById('cfg-siswa')) document.getElementById('cfg-siswa').value = data.siswa;
                if(document.getElementById('cfg-guru')) document.getElementById('cfg-guru').value = data.guru;
                if(document.getElementById('cfg-rombel')) document.getElementById('cfg-rombel').value = data.rombel;

                // Trigger animasi pergerakan chart/angka secara live
                initAnalytics();
                if(typeof updateQuickStats === 'function') updateQuickStats();
            }
        });
        setTimeout(applyAllSettings, 500);

        // --- NOTIFICATION ENGINE ---
        let notifData = JSON.parse(localStorage.getItem('notif_data') || '[]');
        let unreadCnt = 0;
        function addNotif(msg, type='info') {
            const n = { msg, type, time: new Date().toLocaleTimeString('id-ID',{hour12:false}), id: Date.now() };
            notifData.unshift(n);
            if(notifData.length > 15) notifData.pop();
            localStorage.setItem('notif_data', JSON.stringify(notifData));
            unreadCnt++; renderNotifBadge(); renderNotifList();
        }
        function renderNotifBadge() { const b=document.getElementById('notif-badge'); if(!b) return; if(unreadCnt>0){b.style.display='flex';b.textContent=unreadCnt>9?'9+':unreadCnt;}else{b.style.display='none';} }
        function renderNotifList() {
            const c=document.getElementById('notif-list'); if(!c) return;
            if(!notifData.length){c.innerHTML='<div style="padding:20px;text-align:center;color:#555;font-size:0.6rem;letter-spacing:2px;">NO_ACTIVE_ALERTS</div>';return;}
            c.innerHTML=notifData.map(n=>`<div class="notif-item"><div class="notif-msg" style="color:${n.type==='error'?'var(--hud-accent)':n.type==='warn'?'var(--hud-warning)':'#ddd'}">${n.msg}</div><div class="notif-time">[${n.time}]</div></div>`).join('');
        }
        window.toggleNotifPanel = () => { const p=document.getElementById('notif-panel'); if(!p) return; const open=p.style.display==='block'; p.style.display=open?'none':'block'; if(!open){unreadCnt=0;renderNotifBadge();} if(window.playTacSound) playTacSound('click'); };
        window.clearNotifs = () => { notifData=[]; localStorage.setItem('notif_data','[]'); unreadCnt=0; renderNotifBadge(); renderNotifList(); };
        document.addEventListener('click', (e) => { const p=document.getElementById('notif-panel'),w=document.getElementById('notif-wrap'); if(p&&w&&!w.contains(e.target)&&!p.contains(e.target)) p.style.display='none'; });
        renderNotifList(); renderNotifBadge();
        // Hook notif to auth
        const _origOnAuth = window.onAuthStateChanged;
        setTimeout(()=>{ if(auth){ onAuthStateChanged(auth,(u)=>{ if(u) addNotif('Admin uplink: '+u.email.split('@')[0].toUpperCase()+' CONNECTED'); }); }}, 2000);

        // --- ANALYTICS ENGINE ---
        function countUp(el, target, suffix='', dur=1500) {
            if(!el) return; const t0=performance.now();
            const tick=(now)=>{ const p=Math.min((now-t0)/dur,1),e=1-Math.pow(1-p,3); el.textContent=Math.round(target*e)+suffix; if(p<1) requestAnimationFrame(tick); };
            requestAnimationFrame(tick);
        }
        function initAnalytics() {
            const d = { siswa:parseInt(localStorage.getItem('stat_siswa')||'156'), guru:parseInt(localStorage.getItem('stat_guru')||'12'), rombel:parseInt(localStorage.getItem('stat_rombel')||'6') };
            setTimeout(()=>{
                countUp(document.getElementById('stat-siswa'),d.siswa);
                countUp(document.getElementById('stat-guru'),d.guru);
                countUp(document.getElementById('stat-rombel'),d.rombel);
                countUp(document.getElementById('stat-integrity'),100,'%');
                setTimeout(()=>{
                    const bS=document.getElementById('bar-siswa'),bG=document.getElementById('bar-guru'),bR=document.getElementById('bar-rombel'),bI=document.getElementById('bar-integrity');
                    if(bS) bS.style.width=Math.min((d.siswa/200)*100,100)+'%';
                    if(bG) bG.style.width=Math.min((d.guru/20)*100,100)+'%';
                    if(bR) bR.style.width=Math.min((d.rombel/8)*100,100)+'%';
                    if(bI) bI.style.width='100%';
                },300);
            },900);
        }
        initAnalytics();

        // --- TACTICAL CALENDAR ENGINE ---
        let calNow = new Date();
        const calDefaultEvents = [
            {date:'2026-04-21',title:'Hari Kartini',type:'national'},
            {date:'2026-05-02',title:'Hardiknas',type:'national'},
            {date:'2026-05-01',title:'Hari Buruh',type:'holiday'},
            {date:'2026-06-01',title:'Pancasila Day',type:'national'},
        ];
        let calEvents = [...calDefaultEvents, ...JSON.parse(localStorage.getItem('cal_events')||'[]')];
        function renderCalendar() {
            const grid=document.getElementById('cal-grid'),label=document.getElementById('cal-month-label'),evList=document.getElementById('cal-events');
            if(!grid) return;
            const y=calNow.getFullYear(),m=calNow.getMonth(),today=new Date();
            const mNames=['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER'];
            if(label) label.textContent=mNames[m]+' // '+y;
            const firstDay=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),pad=firstDay===0?6:firstDay-1;
            const heads=['MON','TUE','WED','THU','FRI','SAT','SUN'];
            let html=heads.map(d=>`<div class="cal-day-head">${d}</div>`).join('');
            for(let i=0;i<pad;i++) html+=`<div class="cal-day empty"></div>`;
            for(let d=1;d<=days;d++) {
                const ds=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
                const isT=d===today.getDate()&&m===today.getMonth()&&y===today.getFullYear();
                const hasE=calEvents.some(e=>e.date===ds);
                html+=`<div class="cal-day${isT?' today':''}${hasE?' has-event':''}" onclick="showDayEvents('${ds}')">${d}</div>`;
            }
            grid.innerHTML=html;
            const mEvs=calEvents.filter(e=>e.date.startsWith(`${y}-${String(m+1).padStart(2,'0')}`));
            if(evList) evList.innerHTML=mEvs.length?mEvs.map(e=>`<div class="cal-event-item"><span>${e.title}</span><span class="cal-event-date">${e.date.slice(8)}</span></div>`).join('') : '<div style="color:#555;font-size:0.6rem;text-align:center;padding:10px;letter-spacing:2px;">NO_EVENTS_THIS_MONTH</div>';
        }
        window.navigateCal = (dir) => { calNow.setMonth(calNow.getMonth()+dir); renderCalendar(); if(window.playTacSound) playTacSound('click'); };
        window.showDayEvents = (ds) => { const evs=calEvents.filter(e=>e.date===ds); if(evs.length) window.showToast(evs.map(e=>e.title).join(' | ')); };
        renderCalendar();

        // --- STATUS MONITOR (LINK CHECKER) ---
        async function checkLink(url) {
            try { const ctrl=new AbortController(); const tid=setTimeout(()=>ctrl.abort(),5000); await fetch(url,{method:'HEAD',signal:ctrl.signal,mode:'no-cors'}); clearTimeout(tid); return 'online'; }
            catch(e) { return e.name==='AbortError'?'slow':'online'; }
        }
        async function runStatusMonitor() {
            const btns=document.querySelectorAll('.tactical-btn');
            for(const btn of btns) {
                const href=btn.getAttribute('href'); if(!href) continue;
                let dot=btn.querySelector('.link-status-dot');
                if(!dot){ dot=document.createElement('div'); dot.className='link-status-dot checking'; btn.appendChild(dot); }
                const status=await checkLink(href);
                dot.className='link-status-dot'+(status==='slow'?' checking':status==='offline'?' offline':'');
            }
        }
        setTimeout(runStatusMonitor, 3000);
        setInterval(runStatusMonitor, 300000);

        // --- MOBILE HELPERS ---
        window.scrollToTop = (el) => {
            window.scrollTo({top:0,behavior:'smooth'});
            document.querySelectorAll('.mob-nav-btn').forEach(b=>b.classList.remove('mob-active'));
            if(el) el.classList.add('mob-active');
        };
        window.focusMobileTerminal = () => {
            const t=document.getElementById('terminal-input'); if(t){t.focus();t.scrollIntoView({behavior:'smooth',block:'center'});}
            document.querySelectorAll('.mob-nav-btn').forEach(b=>b.classList.remove('mob-active'));
            event?.currentTarget?.classList.add('mob-active');
        };
        window.mobileVault = () => {
            document.querySelectorAll('.mob-nav-btn').forEach(b=>b.classList.remove('mob-active'));
            event?.currentTarget?.classList.add('mob-active');
            processTerminal('vault');
        };

        // --- EXTRA TERMINAL COMMANDS ---
        const _origProcess=processTerminal;
        const _extraCmds = async (cmd) => {
            const c=cmd.toLowerCase().trim();
            if(c==='whoami') return `OPERATOR: ANGGI RAHADIAN // LEAD_DATA_OPS // NODE: SDN02-CIBADAK // TIER-1 CLEARANCE`;
            if(c==='date') { const n=new Date(); return `DATE: ${n.toLocaleDateString('id-ID',{weekday:'long',year:'numeric',month:'long',day:'numeric'})} // ${n.toLocaleTimeString('id-ID',{hour12:false})}`; }
            if(c==='links') return `ACTIVE_LINKS: [DAPODIK] [VERVAL_PD] [VERVAL_PTK] [ARKAS] [INFO_GTK] [SDM_DATA] // STATUS: MONITORING`;
            if(c==='mission') return `ACTIVE_MISSIONS: Check deadline-list panel above for current objectives.`;
            if(c==='theme') return `THEME_CMD: Type &apos;theme cyan&apos;, &apos;theme red&apos;, &apos;theme gold&apos;, &apos;theme ghost&apos;, &apos;theme purple&apos;`;
            if(c==='theme cyan') { applyTheme('#00e5ff','#00ffaa','#ff0055'); return `THEME_SET: CYAN_OPS`; }
            if(c==='theme red') { applyTheme('#ff0055','#ff4488','#ffaa00'); return `THEME_SET: RED_ALERT`; }
            if(c==='theme gold') { applyTheme('#ffaa00','#ffcc44','#00e5ff'); return `THEME_SET: GOLD_COMMAND`; }
            if(c==='theme ghost') { applyTheme('#00ff9d','#00ff9d','#ff5500'); return `THEME_SET: GHOST_PROTOCOL`; }
            if(c==='theme purple') { applyTheme('#b040ff','#cc66ff','#00ffaa'); return `THEME_SET: PURPLE_HAZE`; }
            if(c==='settings') { openSettings(); return `SETTINGS_PANEL: OPENED`; }
            if(c==='analytics') { initAnalytics(); return `ANALYTICS: REFRESHING_DATA...`; }
            if(c==='calendar') { const el=document.querySelector('.calendar-panel'); if(el) el.scrollIntoView({behavior:'smooth'}); return `CALENDAR: SCROLLED_INTO_VIEW`; }
            if(c==='ping') return `PING_STATUS: Running status monitor on all ${document.querySelectorAll('.tactical-btn').length} external nodes...`;
            if(c==='notify test') { addNotif('TEST_NOTIFICATION: System check complete.'); return `NOTIFICATION_SENT`; }
            if(c==='help') return `COMMANDS_V4: [HELP] [STATUS] [WHOAMI] [DATE] [LINKS] [MISSION] [THEME] [SETTINGS] [ANALYTICS] [CALENDAR] [PING] [VAULT] [STEALTH] [MATRIX] [SCAN] [POWER] [NOTES] [REBOOT] [CLEAR] [DAPODIK] [ARKAS] [TRAFFIC --ON/--OFF] [NOTIFY TEST]`;
            return null;
        };
        // Patch processTerminal to add extra commands
        const _oldProcessTerminal = processTerminal;
        processTerminal = async (cmd) => {
            const extra = await _extraCmds(cmd);
            if(extra !== null) {
                const tH=document.getElementById('terminal-history'),tS=document.getElementById('term-scroll-area'),tIn=document.getElementById('terminal-input');
                const line=document.createElement('div'); line.className='terminal-line';
                line.innerHTML=`<span class="terminal-prompt">ops@sdn02cibadak:~$</span> <span style="color:#fff">${cmd}</span><br/><span class="terminal-res">&gt; <span class="type-target"></span><span class="typing-cursor"></span></span>`;
                tH.appendChild(line);
                const tgt=line.querySelector('.type-target'),cur=line.querySelector('.typing-cursor'); let i=0; tIn.disabled=true;
                function tw(){if(i<extra.length){tgt.innerHTML+=extra.charAt(i);i++;if(tS)tS.scrollTop=tS.scrollHeight;setTimeout(tw,12);}else{cur.style.display='none';tIn.disabled=false;tIn.focus();}}
                tw(); if(window.playTacSound) playTacSound('access');
            } else {
                _oldProcessTerminal(cmd);
            }
        };

        // =================================================================
        // WAVE 2 FEATURES ENGINE v4.1
        // =================================================================

        // --- PARTICLE SYSTEM ---
        (function initParticles(){
            const c=document.getElementById('particle-canvas'); if(!c) return;
            const ctx=c.getContext('2d'); let w,h,particles=[];
            function resize(){w=c.width=window.innerWidth;h=c.height=window.innerHeight;}
            resize(); window.addEventListener('resize',resize);
            for(let i=0;i<60;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.5+0.3,dx:(Math.random()-0.5)*0.3,dy:(Math.random()-0.5)*0.3,a:Math.random()*0.5+0.2});
            function draw(){ctx.clearRect(0,0,w,h);particles.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle=`rgba(0,229,255,${p.a})`;ctx.fill();p.x+=p.dx;p.y+=p.dy;if(p.x<0||p.x>w)p.dx*=-1;if(p.y<0||p.y>h)p.dy*=-1;});requestAnimationFrame(draw);}
            draw();
        })();

        // --- SCROLL PROGRESS BAR ---
        window.addEventListener('scroll',()=>{const s=document.getElementById('scroll-progress');if(!s)return;const h=document.documentElement.scrollHeight-window.innerHeight;const p=(window.scrollY/h)*100;s.style.width=p+'%';});

        // --- NAME DECRYPT EFFECT ---
        (function nameDecrypt(){
            const el=document.getElementById('name-decrypt');if(!el)return;
            const final='ANGGI RAHADIAN',chars='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%';
            let iter=0;
            setTimeout(()=>{
                const interval=setInterval(()=>{
                    el.textContent=final.split('').map((c,i)=>i<iter?final[i]:c===' '?' ':chars[Math.floor(Math.random()*chars.length)]).join('');
                    if(iter>=final.length)clearInterval(interval);
                    iter+=0.5;
                },40);
            },1500);
        })();

        // --- STAGGER ANIMATION FOR TACTICAL BUTTONS ---
        setTimeout(()=>{
            document.querySelectorAll('.tactical-btn').forEach((btn,i)=>{
                btn.classList.add('stagger-in');
                btn.style.animationDelay=(i*0.1)+'s';
            });
        },800);

        // --- RIPPLE EFFECT ---
        document.querySelectorAll('.tactical-btn, .btn-tac, .folder-access, .mob-nav-btn').forEach(el=>{
            el.classList.add('ripple-host');
            el.addEventListener('click',(e)=>{
                const r=document.createElement('div');r.className='ripple-wave';
                const rect=el.getBoundingClientRect();
                const sz=Math.max(rect.width,rect.height);
                r.style.width=r.style.height=sz+'px';
                r.style.left=(e.clientX-rect.left-sz/2)+'px';
                r.style.top=(e.clientY-rect.top-sz/2)+'px';
                el.appendChild(r);setTimeout(()=>r.remove(),600);
            });
        });

        // --- COLLAPSIBLE PANELS ---
        window.togglePanel = (header) => {
            header.classList.toggle('collapsed');
            const body=header.nextElementSibling;
            if(body) body.classList.toggle('hidden');
            if(window.playTacSound) playTacSound('click');
        };

        // --- SMART NOTES ENGINE ---
        let smartNotes=JSON.parse(localStorage.getItem('smart_notes')||'[]');
        let noteFilter='ALL';
        window.filterNotes=(tag,el)=>{
            noteFilter=tag;
            document.querySelectorAll('.note-tag').forEach(t=>t.classList.remove('active'));
            if(el) el.classList.add('active');
            renderNotes();
        };
        window.addSmartNote=()=>{
            const inp=document.getElementById('note-input'),sel=document.getElementById('note-tag-select');
            const txt=inp.value.trim(); if(!txt) return;
            smartNotes.unshift({text:txt,tag:sel.value,time:new Date().toLocaleTimeString('id-ID',{hour12:false}),date:new Date().toLocaleDateString('id-ID'),id:Date.now()});
            localStorage.setItem('smart_notes',JSON.stringify(smartNotes));
            inp.value=''; renderNotes();
            if(window.playTacSound) playTacSound('access');
        };
        document.getElementById('note-input')?.addEventListener('keydown',(e)=>{if(e.key==='Enter')addSmartNote();});
        window.deleteNote=(id)=>{
            smartNotes=smartNotes.filter(n=>n.id!==id);
            localStorage.setItem('smart_notes',JSON.stringify(smartNotes));
            renderNotes();
        };
        function renderNotes(){
            const list=document.getElementById('notes-list'),cnt=document.getElementById('note-count');
            if(!list) return;
            const filtered=noteFilter==='ALL'?smartNotes:smartNotes.filter(n=>n.tag===noteFilter);
            if(cnt) cnt.textContent=smartNotes.length;
            if(!filtered.length){
                list.innerHTML=`
                    <div class="empty-state-container">
                        <i class="fa-solid fa-note-sticky empty-state-icon"></i>
                        <div class="empty-state-text">NO NOTES FOUND</div>
                        <div class="empty-state-sub">CLEAN_SLATE // READY FOR INPUT</div>
                    </div>`;
                return;
            }
            list.innerHTML=filtered.map(n=>{
                const tagColor=n.tag==='URGENT'?'var(--hud-accent)':n.tag==='DAPODIK'?'var(--hud-success)':n.tag==='KEUANGAN'?'var(--hud-warning)':'var(--hud-primary)';
                return `<div class="note-card" style="border-left-color:${tagColor}"><div class="note-text">${n.text}</div><div class="note-meta"><span><span class="note-tag-label" style="background:${tagColor}22;color:${tagColor}">${n.tag}</span> ${n.date} ${n.time}</span><i class="fa-solid fa-trash note-del" onclick="deleteNote(${n.id})"></i></div></div>`;
            }).join('');
        }
        renderNotes();

        // pad already declared above — no duplicate needed

        // --- PROFILE CARD EXPORT ---
        window.exportProfileCard = () => {
            const canvas=document.createElement('canvas');
            canvas.width=600;canvas.height=320;
            const ctx=canvas.getContext('2d');
            // Background
            const grad=ctx.createLinearGradient(0,0,600,320);
            grad.addColorStop(0,'#030816');grad.addColorStop(1,'#0a1628');
            ctx.fillStyle=grad;ctx.fillRect(0,0,600,320);
            // Border
            ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--hud-primary').trim()||'#00e5ff';
            ctx.lineWidth=2;ctx.strokeRect(10,10,580,300);
            // Grid lines
            ctx.strokeStyle='rgba(0,229,255,0.06)';ctx.lineWidth=1;
            for(let i=0;i<600;i+=30){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,320);ctx.stroke();}
            for(let i=0;i<320;i+=30){ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(600,i);ctx.stroke();}
            // Text
            const pri=getComputedStyle(document.documentElement).getPropertyValue('--hud-primary').trim()||'#00e5ff';
            ctx.fillStyle='#ffaa00';ctx.font='10px Share Tech Mono';ctx.fillText('LEAD DATA OPERATOR',40,50);
            ctx.fillStyle='#ffffff';ctx.font='bold 32px Rajdhani';ctx.fillText('ANGGI RAHADIAN',40,90);
            ctx.fillStyle=pri;ctx.font='12px Share Tech Mono';
            ctx.fillText('NODE: SDN 02 CIBADAK // NPSN: 20202659',40,120);
            ctx.fillText('KAB. SUKABUMI // JAWA BARAT',40,140);
            ctx.fillStyle='#00ffaa';ctx.fillText('TIER 1 CLEARANCE // ADMINISTRATOR DATA OPS',40,170);
            ctx.fillStyle='#ffaa00';ctx.font='10px Share Tech Mono';ctx.fillText('PENGELOLA DATA PENDIDIKAN // EST. 2010',40,200);
            // Corner brackets
            ctx.strokeStyle=pri;ctx.lineWidth=2;
            ctx.beginPath();ctx.moveTo(20,20);ctx.lineTo(20,50);ctx.stroke();
            ctx.beginPath();ctx.moveTo(20,20);ctx.lineTo(50,20);ctx.stroke();
            ctx.beginPath();ctx.moveTo(580,20);ctx.lineTo(580,50);ctx.stroke();
            ctx.beginPath();ctx.moveTo(580,20);ctx.lineTo(550,20);ctx.stroke();
            ctx.beginPath();ctx.moveTo(20,300);ctx.lineTo(20,270);ctx.stroke();
            ctx.beginPath();ctx.moveTo(20,300);ctx.lineTo(50,300);ctx.stroke();
            ctx.beginPath();ctx.moveTo(580,300);ctx.lineTo(580,270);ctx.stroke();
            ctx.beginPath();ctx.moveTo(580,300);ctx.lineTo(550,300);ctx.stroke();
            // Timestamp
            ctx.fillStyle='#555';ctx.font='9px Share Tech Mono';
            ctx.fillText('GENERATED: '+new Date().toISOString(),40,285);
            ctx.fillText('DATA COMMAND CENTER // V4.1',350,285);
            // Download
            const link=document.createElement('a');
            link.download='OPS_CARD_ANGGI_RAHADIAN.png';
            link.href=canvas.toDataURL('image/png');
            link.click();
            window.showToast('PROFILE_CARD_EXPORTED');
            if(window.playTacSound) playTacSound('access');
        };

        // --- QUICK STATS BAR UPDATER ---
        function updateQuickStats(){
            const qs=document.getElementById('qs-siswa'),qg=document.getElementById('qs-guru'),qb=document.getElementById('qs-batt'),qt=document.getElementById('qs-temp'),qu=document.getElementById('qs-uptime');
            if(qs) qs.textContent=localStorage.getItem('stat_siswa')||'156';
            if(qg) qg.textContent=localStorage.getItem('stat_guru')||'12';
            if(qt){const we=document.getElementById('weather-temp');qt.textContent=we?we.textContent:'--';}
            if('getBattery' in navigator){navigator.getBattery().then(b=>{if(qb) qb.textContent=Math.round(b.level*100)+'%';});}
        }
        setInterval(updateQuickStats,5000);
        setTimeout(updateQuickStats,3000);
        // Uptime in quick stats
        setInterval(()=>{const qu=document.getElementById('qs-uptime'),u=document.getElementById('uptime');if(qu&&u)qu.textContent=u.textContent.substring(0,5);},2000);

        // --- TOUCH SWIPE FOR MOBILE ---
        let touchStartX=0,touchStartY=0;
        document.addEventListener('touchstart',(e)=>{touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY;},{passive:true});
        document.addEventListener('touchend',(e)=>{
            const dx=e.changedTouches[0].clientX-touchStartX,dy=e.changedTouches[0].clientY-touchStartY;
            if(Math.abs(dx)>60&&Math.abs(dy)<40){
                if(dx>0&&document.getElementById('folderModal').style.display==='flex') window.closeAppFolder();
                if(dx<0) window.openAppFolder();
            }
        },{passive:true});

        // =================================================================
        // TACTICAL CONTEXT MENU ENGINE (CUSTOM RIGHT-CLICK)
        // =================================================================
        const ctxMenu = document.getElementById('tactical-context-menu');

        // 1. Matikan klik kanan bawaan dan munculkan menu kita
        document.addEventListener('contextmenu', (e) => {
            // Hindari memblokir klik kanan jika mengklik input (agar bisa Copy/Paste manual)
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

            e.preventDefault(); // Matikan klik kanan default Chrome/Edge

            if(window.playTacSound) window.playTacSound('click');

            // Tampilkan dulu agar kita bisa mengukur tinggi dan lebarnya
            ctxMenu.style.display = 'block';

            // Ambil dimensi
            const menuWidth = ctxMenu.offsetWidth;
            const menuHeight = ctxMenu.offsetHeight;
            const windowWidth = window.innerWidth;
            const windowHeight = window.innerHeight;

            // Kalkulasi posisi kursor mouse
            let xPos = e.clientX;
            let yPos = e.clientY;

            // Jika posisi menu menabrak ujung kanan layar, geser ke kiri
            if (xPos + menuWidth > windowWidth) {
                xPos = windowWidth - menuWidth - 10; 
            }
            // Jika posisi menu menabrak ujung bawah layar, geser ke atas
            if (yPos + menuHeight > windowHeight) {
                yPos = windowHeight - menuHeight - 10;
            }

            // Terapkan kordinat ke menu
            ctxMenu.style.left = `${xPos}px`;
            ctxMenu.style.top = `${yPos}px`;
        });

        // 2. Sembunyikan menu saat mengklik di mana pun di luar menu
        document.addEventListener('click', (e) => {
            if (ctxMenu.style.display === 'block') {
                ctxMenu.style.display = 'none';
            }
        });

        // 3. Jembatani klik menu ke fungsi Terminal yang sudah ada!
        window.ctxAction = (action) => {
            if(window.playTacSound) window.playTacSound('access');

            // Kita panggil perintah seolah-olah kita mengetikkannya di terminal
            if(typeof processTerminal === 'function') {
                if(action === 'vault') processTerminal('vault');
                if(action === 'stealth') processTerminal('stealth');
                if(action === 'clear') processTerminal('clear');
                if(action === 'matrix') processTerminal('matrix --run');
                if(action === 'scan') processTerminal('scan');
                if(action === 'reboot') processTerminal('reboot');
            }

            // Sembunyikan menu setelah menu dipilih
            ctxMenu.style.display = 'none';
        };

        // =================================================================
        // OMNI-SEARCH ENGINE (CTRL+K / CMD+K)
        // =================================================================
        const omniOverlay = document.getElementById('omni-overlay');
        const omniBox = document.getElementById('omni-box');
        const omniInput = document.getElementById('omni-input');
        const omniResults = document.getElementById('omni-results');

        let omniDataList =[];
        let omniSelectedIndex = -1;

        // 1. FUNGSI UNTUK MEMBUKA & MENUTUP OMNI-SEARCH
        window.toggleOmniSearch = (forceOpen = null) => {
            const isOpen = omniOverlay.style.display === 'flex';
            if (forceOpen === true || !isOpen) {
                // BUKA
                omniOverlay.style.display = 'flex';
                setTimeout(() => {
                    omniOverlay.style.opacity = '1';
                    omniBox.style.transform = 'translateY(0)';
                    omniInput.focus();
                    omniInput.value = '';
                    buildOmniData(); // Kumpulkan semua data terbaru
                    renderOmniResults(); // Tampilkan data default
                }, 10);
                if(window.playTacSound) window.playTacSound('access');
            } else {
                // TUTUP
                omniOverlay.style.opacity = '0';
                omniBox.style.transform = 'translateY(-20px)';
                setTimeout(() => omniOverlay.style.display = 'none', 200);
            }
        };

        // 2. TANGKAP SHORTCUT KEYBOARD (CTRL + K)
        document.addEventListener('keydown', (e) => {
            // Deteksi Ctrl+K (Windows/Linux) atau Cmd+K (Mac)
            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
                e.preventDefault();
                toggleOmniSearch();
            }

            // Tutup pakai tombol ESC
            if (e.key === 'Escape' && omniOverlay.style.display === 'flex') {
                toggleOmniSearch(false);
            }
        });

        // Tutup jika area background gelap diklik
        omniOverlay.addEventListener('click', (e) => {
            if (e.target === omniOverlay) toggleOmniSearch(false);
        });

        // 3. KUMPULKAN SEMUA DATA (LINKS, VAULT, PERINTAH) KE DALAM 1 DAFTAR
        function buildOmniData() {
            omniDataList =[];

            // A. Masukkan Perintah Sistem (Actions)
            const actions =[
                { title: "Buka Brankas (Vault)", sub: "Akses data tersandi", type: "ACTION", icon: "fa-vault", run: () => processTerminal('vault') },
                { title: "Dashboard SPMB", sub: "Admin Panel PPDB", type: "ACTION", icon: "fa-users-viewfinder", run: () => window.openSPMBAdmin() },
                { title: "Settings / Pengaturan", sub: "Konfigurasi Sistem", type: "ACTION", icon: "fa-sliders", run: () => window.openSettings() },
                { title: "Stealth Mode", sub: "Sembunyikan aktivitas", type: "ACTION", icon: "fa-user-secret", run: () => processTerminal('stealth') },
                { title: "Buka Semua Folder Aplikasi", sub: "Directory Apps", type: "ACTION", icon: "fa-folder-tree", run: () => window.openAppFolder() }
            ];

            // B. Masukkan Web External (Links)
            const links =[
                { title: "Dapodik Cloud", sub: "dapo.kemdikbud.go.id", type: "LINK", icon: "fa-server", run: () => window.open('https://dapo.kemendikdasmen.go.id/', '_blank') },
                { title: "Verval PD", sub: "Data Peserta Didik", type: "LINK", icon: "fa-user-graduate", run: () => window.open('https://vervalpd.data.kemendikdasmen.go.id/', '_blank') },
                { title: "Verval PTK", sub: "Data Pendidik", type: "LINK", icon: "fa-chalkboard-user", run: () => window.open('https://vervalptk.data.kemendikdasmen.go.id/', '_blank') },
                { title: "Arkas", sub: "Sistem Keuangan", type: "LINK", icon: "fa-file-invoice-dollar", run: () => window.open('https://arkas.kemendikdasmen.go.id/', '_blank') }
            ];

            omniDataList = [...actions, ...links];

            // C. Masukkan Data Brankas / Vault (Kalau sudah ditarik dari Firebase)
            if (window.vData && window.vData.length > 0) {
                window.vData.forEach(item => {
                    omniDataList.push({
                        title: item.label,
                        sub: `Kategori: ${item.category}`,
                        type: "VAULT",
                        icon: "fa-key",
                        // Saat ditekan, langsung copy ke clipboard
                        run: () => {
                            navigator.clipboard.writeText(item.value);
                            window.showToast(`DATA ${item.label} COPIED TO CLIPS!`);
                            if(window.playTacSound) window.playTacSound('access');
                        }
                    });
                });
            }
        }

        // 4. TAMPILKAN HASIL PENCARIAN
        function renderOmniResults(query = "") {
            omniResults.innerHTML = "";
            let filtered = omniDataList;

            // Filter data kalau ada yang diketik
            if (query.trim() !== "") {
                const q = query.toLowerCase().trim();
                filtered = omniDataList.filter(item => 
                    item.title.toLowerCase().includes(q) || item.sub.toLowerCase().includes(q)
                );
            }

            // Batasi hasil maksimal 15 agar tidak terlalu berat
            filtered = filtered.slice(0, 15);

            if (filtered.length === 0) {
                omniResults.innerHTML = `<div style="text-align:center; padding:30px; color:#666; font-family:'Orbitron';">UNKNOWN_QUERY_OR_DATA_NOT_FOUND</div>`;
                return;
            }

            filtered.forEach((item, index) => {
                const div = document.createElement('div');
                div.className = `omni-item ${index === omniSelectedIndex ? 'selected' : ''}`;
                // Setup beda warna badge berdasarkan tipe
                let badgeClass = 'link';
                if(item.type === 'ACTION') badgeClass = 'action';
                if(item.type === 'VAULT') badgeClass = 'vault';

                div.innerHTML = `
                    <div>
                        <div class="omni-item-title"><i class="fa-solid ${item.icon}"></i> ${item.title}</div>
                        <div class="omni-item-sub">${item.sub}</div>
                    </div>
                    <div class="omni-type-badge ${badgeClass}">${item.type}</div>
                `;

                // Jika di-klik pakai mouse
                div.addEventListener('click', () => {
                    item.run();
                    toggleOmniSearch(false);
                });

                // Jika di-hover, pindahkan highlight ke item ini
                div.addEventListener('mousemove', () => {
                    if (omniSelectedIndex !== index) {
                        omniSelectedIndex = index;
                        updateOmniSelection();
                    }
                });

                // Simpan fungsi run di elemen DOM agar bisa dipanggil oleh tombol Enter
                div.dataset.index = index;
                div.runCommand = item.run;
                omniResults.appendChild(div);
            });
        }

        // 5. NAVIGASI KEYBOARD (NAIK, TURUN, ENTER)
        omniInput.addEventListener('input', (e) => {
            omniSelectedIndex = 0; // Reset seleksi ke paling atas
            renderOmniResults(e.target.value);
            if(window.playTypeSound) window.playTypeSound();
        });

        omniInput.addEventListener('keydown', (e) => {
            const items = omniResults.querySelectorAll('.omni-item');
            if (items.length === 0) return;

            if (e.key === 'ArrowDown') {
                e.preventDefault();
                omniSelectedIndex = (omniSelectedIndex + 1) % items.length;
                updateOmniSelection();
            } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                omniSelectedIndex = (omniSelectedIndex - 1 + items.length) % items.length;
                updateOmniSelection();
            } else if (e.key === 'Enter') {
                e.preventDefault();
                const selectedItem = items[omniSelectedIndex];
                if (selectedItem && selectedItem.runCommand) {
                    selectedItem.runCommand();
                    toggleOmniSearch(false);
                }
            }
        });

        function updateOmniSelection() {
            const items = omniResults.querySelectorAll('.omni-item');
            items.forEach((el, index) => {
                if (index === omniSelectedIndex) {
                    el.classList.add('selected');
                    el.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); // Auto-scroll
                } else {
                    el.classList.remove('selected');
                }
            });
        }


        // =================================================================
        // SCI-FI AUDIO ENGINE (WEB AUDIO API)
        // =================================================================
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        let audioCtx;

        function initAudio() {
            if (!audioCtx) {
                audioCtx = new AudioContext();
                // Attach audio to all buttons dynamically once audio is initialized
                attachAudioListeners();
            }
            if (audioCtx.state === 'suspended') audioCtx.resume();
        }

        // Jalankan initAudio saat ada interaksi pertama agar diizinkan browser
        document.body.addEventListener('click', initAudio, { once: true });
        document.body.addEventListener('mousemove', initAudio, { once: true });

        window.playHoverSound = () => {
            if (!audioCtx || audioCtx.state !== 'running') return;
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, audioCtx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(1200, audioCtx.currentTime + 0.05);
            gain.gain.setValueAtTime(0.015, audioCtx.currentTime); // Sangat pelan
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.05);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.05);
        };

        window.playClickSound = () => {
            if (!audioCtx || audioCtx.state !== 'running') return;
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = 'square';
            osc.frequency.setValueAtTime(300, audioCtx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(100, audioCtx.currentTime + 0.1);
            gain.gain.setValueAtTime(0.03, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.1);
        };

        window.playSuccessSound = () => {
            if (!audioCtx || audioCtx.state !== 'running') return;
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(400, audioCtx.currentTime);
            osc.frequency.setValueAtTime(600, audioCtx.currentTime + 0.1);
            osc.frequency.setValueAtTime(800, audioCtx.currentTime + 0.2);
            gain.gain.setValueAtTime(0, audioCtx.currentTime);
            gain.gain.linearRampToValueAtTime(0.04, audioCtx.currentTime + 0.1);
            gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.3);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.3);
        };

        function attachAudioListeners() {
            document.querySelectorAll('button, .action-btn, .nav-btn, .dashboard-card, .omni-item').forEach(btn => {
                // Prevent duplicate listeners
                btn.removeEventListener('mouseenter', window.playHoverSound);
                btn.removeEventListener('click', window.playClickSound);

                btn.addEventListener('mouseenter', window.playHoverSound);
                btn.addEventListener('click', window.playClickSound);
            });
        }

        // Buat observer jika ada elemen baru yang dirender (seperti baris tabel atau swal)
        const audioObserver = new MutationObserver((mutations) => {
            if(audioCtx && audioCtx.state === 'running') attachAudioListeners();
        });
        audioObserver.observe(document.body, { childList: true, subtree: true });

        // =================================================================
        // SPMB ADMIN NODE UPLINK & LOGIC
        // =================================================================
        const SPMB_SUPA_URL = 'https://eqoyfejrukbwkgdsqrvg.supabase.co';
        const SPMB_SUPA_KEY = 'sb_publishable_NxSguSXZlFoJwCbXdHs4MQ_dP00crUC';
        const SPMB_HEAD = { 'apikey': SPMB_SUPA_KEY, 'Authorization': 'Bearer ' + SPMB_SUPA_KEY };
        const SPMB_HEAD_JSON = { 'apikey': SPMB_SUPA_KEY, 'Authorization': 'Bearer ' + SPMB_SUPA_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' };

        let spmbDataCache = [];
        let spmbLastCount = -1;

        // Auto-Polling (Live Uplink)
        const runSpmbPolling = () => {
            fetch(SPMB_SUPA_URL + '/rest/v1/pendaftar_dapodik?select=id', { headers: SPMB_HEAD })
            .then(r=>r.json())
            .then(res=>{
                const total = res.length;

                // Update elemen UI agar jarvisGreeting bisa baca angkanya
                const statTotalEl = document.getElementById('spmb-stat-total');
                if(statTotalEl) statTotalEl.innerText = total;

                if(spmbLastCount !== -1 && total > spmbLastCount){
                    const diff = total - spmbLastCount;
                    if(window.showToast) window.showToast('SPMB_UPLINK: ACTIVE');

                    // --- JARVIS VOICE NOTIFICATION (REAL-TIME) ---
                    if(window.speak) {
                        window.speak(`Lapor Pak Anggi, ada ${diff} pendaftar baru yang masuk ke sistem S P M B.`);
                    }

                    if(typeof addTerminalLog === 'function') {
                        addTerminalLog('SPMB_NODE', `Incoming Uplink: ${diff} new registration(s) detected.`, true);
                    }
                    if(document.getElementById('modal-spmb-admin').style.display === 'flex'){
                        window.loadSemuaPendaftarSPMB();
                    }
                }

                spmbLastCount = total;
                // Simpan ke localStorage untuk briefing saat login berikutnya
                localStorage.setItem('spmb_last_count', total);

            }).catch(e=>console.log("SPMB Uplink error:", e));
        };

        // Jalankan sekali saat load & set interval
        runSpmbPolling();
        setInterval(runSpmbPolling, 15000);

        window.openSPMBAdmin = () => {
            // === AUTH GATE: CEK LOGIN FIREBASE DULU ===
            if (!window.isOpsLoggedIn) {
                window.showToast("[!] AUTH_GATEWAY_LOCKED: LOGIN REQUIRED", "error");
                addTerminalLog('SECURITY', 'Unauthorized Access Attempt: SPMB Admin Panel Locked', true);
                if(window.playTacSound) window.playTacSound('error');
                return; // BLOCK AKSES
            }

            // Kalau sudah login, buka modal
            document.getElementById('folderModal').style.display = 'none';
            document.getElementById('modal-spmb-admin').style.display = 'flex';
            if(window.playTacSound) window.playTacSound('access');
            window.loadDashboardSPMB();
            window.loadSemuaPendaftarSPMB();
            window.loadMaintenanceStatusSPMB();
        };

        window.closeSPMBAdmin = () => {
            document.getElementById('modal-spmb-admin').style.display = 'none';
            if(window.playTacSound) window.playTacSound('click');
        };

        window.loadDashboardSPMB = () => {
            fetch(SPMB_SUPA_URL + '/rest/v1/pendaftar_dapodik?select=status_pendaftaran', { headers: SPMB_HEAD })
            .then(r=>r.json())
            .then(data=>{
                document.getElementById('spmb-stat-total').innerText = data.length;
                // FIX: Treat NULL/undefined status as "Tahap 1"
                document.getElementById('spmb-stat-t1').innerText = data.filter(d=>(d.status_pendaftaran||'Tahap 1')==='Tahap 1').length;
                document.getElementById('spmb-stat-t2').innerText = data.filter(d=>(d.status_pendaftaran||'Tahap 1')==='Tahap 2').length;
                document.getElementById('spmb-stat-terima').innerText = data.filter(d=>(d.status_pendaftaran||'Tahap 1')==='Diterima').length;
                document.getElementById('spmb-stat-tolak').innerText = data.filter(d=>(d.status_pendaftaran||'Tahap 1')==='Ditolak').length;
            });
        };

        window.loadSemuaPendaftarSPMB = () => {
            fetch(SPMB_SUPA_URL + '/rest/v1/pendaftar_dapodik?select=*&order=created_at.desc', { headers: SPMB_HEAD })
            .then(r=>r.json())
            .then(data=>{
                spmbDataCache = data;
                window.renderTabelPendaftarSPMB(data);
            });
        };

        window.renderTabelPendaftarSPMB = (data) => {
            const tbody = document.getElementById('spmb-body-table');
            if (!data || data.length === 0) {
                tbody.innerHTML = "<tr><td colspan='7' style='text-align:center; padding:30px; font-family:\"Share Tech Mono\"; color:#888;'>NO_DATA_FOUND</td></tr>";
                return;
            }
            let html = '';
            const statusColors = { 'Tahap 1': '#f59e0b', 'Tahap 2': '#8b5cf6', 'Diterima': '#10b981', 'Ditolak': '#ef4444' };
            data.forEach((d, i) => {
                // FIX: Fallback status NULL/undefined ke "Tahap 1"
                const statusAktual = d.status_pendaftaran || 'Tahap 1';
                const warna = statusColors[statusAktual] || '#64748b';
                html += `<tr>
                    <td>${i+1}</td>
                    <td style="font-weight:bold; color:var(--hud-primary);">${d.nama||'-'}</td>
                    <td style="color:#aaa;">${d.nik||'-'}</td>
                    <td style="color:#aaa;">${d.tempat_lahir||''}, ${d.tanggal_lahir||'-'}</td>
                    <td style="color:#aaa;">${d.hp||'-'}</td>
                    <td style="text-align:center;">
                        <select onchange="window.ubahStatusSPMB(${d.id}, this.value)" class="spmb-select" style="color:${warna}; border-color:${warna}">
                            ${['Tahap 1','Tahap 2','Diterima','Ditolak'].map(s=>`<option value="${s}" ${statusAktual===s?'selected':''}>${s}</option>`).join('')}
                        </select>
                    </td>
                    <td style="text-align:center;">
                        <button class="spmb-btn" onclick="window.cetakBuktiLulusSPMB(${d.id})" title="Cetak Checklist Map" style="background:#10b981; color:white;"><i class="fa-solid fa-receipt"></i></button>
                        <button class="spmb-btn" onclick="window.cetakS1SPMB(${d.id})" title="Cetak Formulir S1"><i class="fa-solid fa-print"></i></button>
                        <button class="spmb-btn danger" onclick="window.hapusPendaftarSPMB(${d.id})" title="Hapus"><i class="fa-solid fa-trash"></i></button>
                    </td>
                </tr>`;
            });
            tbody.innerHTML = html;
        };

        window.filterPendaftarSPMB = () => {
            const q = document.getElementById('spmb-search').value.toLowerCase();
            const filtered = spmbDataCache.filter(d => (d.nama||'').toLowerCase().includes(q) || (d.nik||'').includes(q));
            window.renderTabelPendaftarSPMB(filtered);
        };

        window.ubahStatusSPMB = (id, statusBaru) => {
            Swal.fire({
                title: 'OVERRIDE STATUS?',
                text: 'MENGUBAH STATUS MENJADI: ' + statusBaru,
                background: '#00141e', color: '#00ffaa', iconColor: '#00ffaa',
                showCancelButton: true, confirmButtonText: 'EXECUTE', cancelButtonText: 'ABORT',
                confirmButtonColor: '#00e5ff', cancelButtonColor: '#ff0055'
            }).then(r => {
                if (r.isConfirmed) {
                    fetch(SPMB_SUPA_URL + `/rest/v1/pendaftar_dapodik?id=eq.${id}`, {
                        method: 'PATCH',
                        headers: { 'apikey': SPMB_SUPA_KEY, 'Authorization': 'Bearer ' + SPMB_SUPA_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
                        body: JSON.stringify({ status_pendaftaran: statusBaru })
                    }).then(() => {
                        window.showToast('STATUS_UPDATED');
                        window.loadDashboardSPMB();
                        window.loadSemuaPendaftarSPMB();
                    }).catch(()=>window.showToast('ERROR: UPDATE_FAILED'));
                } else { window.loadSemuaPendaftarSPMB(); }
            });
        };

        window.hapusPendaftarSPMB = (id) => {
            Swal.fire({
                title: 'CRITICAL ACTION',
                text: 'DATA WILL BE PERMANENTLY PURGED. CONFIRM DELETION?',
                background: '#00141e', color: '#ff0055', iconColor: '#ff0055',
                showCancelButton: true, confirmButtonText: 'PURGE', cancelButtonText: 'ABORT',
                confirmButtonColor: '#ff0055', cancelButtonColor: '#00e5ff'
            }).then(r => {
                if(r.isConfirmed) {
                    fetch(SPMB_SUPA_URL + `/rest/v1/pendaftar_dapodik?id=eq.${id}`, {
                        method: 'DELETE', headers: { 'apikey': SPMB_SUPA_KEY, 'Authorization': 'Bearer ' + SPMB_SUPA_KEY, 'Prefer': 'return=minimal' }
                    }).then(() => {
                        window.showToast('DATA_PURGED');
                        window.loadDashboardSPMB();
                        window.loadSemuaPendaftarSPMB();
                    });
                }
            });
        };

        window.loadMaintenanceStatusSPMB = () => {
            fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=eq.maintenance&select=status', { headers: SPMB_HEAD })
            .then(r=>r.json())
            .then(data=>{
                if (data.length > 0) {
                    const isOn = data[0].status === 'ON';
                    document.getElementById('tog-spmb-mnt').classList.toggle('on', isOn);
                    document.getElementById('spmb-mnt-status').innerText = 'STATUS: ' + (isOn ? 'MAINTENANCE_ACTIVE' : 'ONLINE');
                    document.getElementById('spmb-mnt-status').style.color = isOn ? '#ff0055' : 'var(--hud-success)';
                }
            });
        };

        // --- FUNGSI TOGGLE MAINTENANCE (INSTAN / OPTIMISTIC UI) ---
        window.toggleSpmbMaintenance = async () => {
            const tog = document.getElementById('tog-spmb-mnt');
            const statusText = document.getElementById('spmb-mnt-status');

            // 1. Cek status tombol saat ini
            const isCurrentlyOn = tog.classList.contains('on');
            const targetStatus = isCurrentlyOn ? 'OFF' : 'ON';

            // 2. UBAH TAMPILAN SECARA INSTAN (Tanpa nunggu server)
            tog.classList.toggle('on');
            statusText.innerText = 'STATUS: ' + (targetStatus === 'ON' ? 'MAINTENANCE_ACTIVE' : 'ONLINE');
            statusText.style.color = targetStatus === 'ON' ? '#ff0055' : 'var(--hud-success)';
            if(window.playTacSound) window.playTacSound('click');

            try {
                // 3. Kirim update ke Supabase di background
                const response = await fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=eq.maintenance', {
                    method: 'PATCH',
                    headers: { 
                        'apikey': SPMB_SUPA_KEY, 
                        'Authorization': 'Bearer ' + SPMB_SUPA_KEY, 
                        'Content-Type': 'application/json', 
                        'Prefer': 'return=minimal' 
                    },
                    body: JSON.stringify({ status: targetStatus })
                });

                // Cek kalau Supabase nolak (Mungkin RLS belum dimatiin)
                if (!response.ok) throw new Error("Supabase Blocked");

                // Munculkan notifikasi sukses
                window.showToast(targetStatus === 'ON' ? 'MNT_MODE_ACTIVATED' : 'MNT_MODE_DISABLED');

            } catch (error) {
                // 4. JIKA GAGAL (Koneksi putus/RLS Supabase belum dimatiin)
                window.showToast("UPDATE GAGAL! CEK RLS SUPABASE", "error");

                // Kembalikan tombol ke posisi semula karena gagal update database
                tog.classList.toggle('on'); 
                statusText.innerText = 'STATUS: ' + (isCurrentlyOn ? 'MAINTENANCE_ACTIVE' : 'ONLINE');
                statusText.style.color = isCurrentlyOn ? '#ff0055' : 'var(--hud-success)';
            }
        };

        window.gantiPasswordAdminSPMB = () => {
            Swal.fire({
                title: 'OVERRIDE PASSWORD',
                html: '<input id="swal-pw1" class="swal2-input" placeholder="NEW PASSWORD" type="password" style="background:#000;color:var(--hud-primary);font-family:Orbitron; border:1px solid var(--hud-primary);"/>'+
                      '<input id="swal-pw2" class="swal2-input" placeholder="VERIFY PASSWORD" type="password" style="background:#000;color:var(--hud-primary);font-family:Orbitron; border:1px solid var(--hud-primary);"/>',
                background: '#00141e', color: '#00ffaa',
                showCancelButton: true, confirmButtonText: 'UPDATE', cancelButtonText: 'ABORT',
                confirmButtonColor: '#00e5ff', cancelButtonColor: '#ff0055',
                preConfirm: () => {
                    const p1 = document.getElementById('swal-pw1').value;
                    const p2 = document.getElementById('swal-pw2').value;
                    if(!p1) { Swal.showValidationMessage('INVALID KEY LENGTH'); return false; }
                    if(p1 !== p2) { Swal.showValidationMessage('KEY MISMATCH'); return false; }
                    return p1;
                }
            }).then(r => {
                if(r.isConfirmed) {
                    fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=eq.admin_password', {
                        method: 'PATCH', headers: { 'apikey': SPMB_SUPA_KEY, 'Authorization': 'Bearer ' + SPMB_SUPA_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
                        body: JSON.stringify({ status: r.value })
                    }).then(() => window.showToast('PASSWORD_UPDATED'));
                }
            });
        };

        window.settingCountdownSPMB = () => {
            fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=in.(jadwal_buka,jadwal_tutup)&select=nama_setting,status', { headers: SPMB_HEAD })
            .then(r=>r.json()).then(data=>{
                let jadwalBuka = '2026-05-01T08:00';
                let jadwalTutup = '2026-06-01T23:59';

                const fmt = (dStr) => {
                    let d = new Date(dStr);
                    if(isNaN(d)) return '';
                    const pad = n => n.toString().padStart(2, '0');
                    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
                };

                data.forEach(d => {
                    if (d.nama_setting === 'jadwal_buka' && d.status) jadwalBuka = fmt(d.status);
                    if (d.nama_setting === 'jadwal_tutup' && d.status) jadwalTutup = fmt(d.status);
                });

                Swal.fire({
                    title: 'SPMB TIMER & AUTO-MAINTENANCE',
                    html: `<style>
                             input[type="datetime-local"]::-webkit-calendar-picker-indicator {
                                 filter: invert(1) sepia(100%) saturate(500%) hue-rotate(130deg); /* Warna cyan/neon */
                                 cursor: pointer;
                             }
                           </style>
                           <div style="font-size:0.65rem; margin-bottom:10px; color:#aaa; font-family:Orbitron;">WAKTU BUKA PENDAFTARAN</div>
                           <input type="datetime-local" id="swal-buka" class="swal2-input" value="${jadwalBuka}" style="background:#000;color:var(--hud-primary);font-family:Orbitron; border:1px solid var(--hud-primary); text-align:center; font-size: 0.9rem; margin-top:0; width: 80%; padding: 0 10px; cursor: pointer;"/>
                           <div style="font-size:0.65rem; margin-top:15px; margin-bottom:10px; color:#aaa; font-family:Orbitron;">WAKTU TUTUP PENDAFTARAN</div>
                           <input type="datetime-local" id="swal-tutup" class="swal2-input" value="${jadwalTutup}" style="background:#000;color:var(--hud-accent);font-family:Orbitron; border:1px solid var(--hud-accent); text-align:center; font-size: 0.9rem; margin-top:0; width: 80%; padding: 0 10px; cursor: pointer;"/>
                           <div style="font-size:0.5rem; margin-top:15px; color:#888;">*Klik logo kalender di ujung kotak untuk memilih tanggal.</div>`,
                    background: '#00141e', color: '#00ffaa',
                    showCancelButton: true, confirmButtonText: 'SAVE_TIMERS', cancelButtonText: 'ABORT',
                    confirmButtonColor: '#00e5ff', cancelButtonColor: '#ff0055'
                }).then(r=>{
                    if(r.isConfirmed){
                        const b = document.getElementById('swal-buka').value;
                        const t = document.getElementById('swal-tutup').value;

                        // Gunakan PATCH agar sama dengan pengaturan Kepsek
                        fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=eq.jadwal_buka', {
                            method: 'PATCH', 
                            headers: { 'apikey': SPMB_SUPA_KEY, 'Authorization': 'Bearer ' + SPMB_SUPA_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, 
                            body: JSON.stringify({ status: b })
                        });

                        fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=eq.jadwal_tutup', {
                            method: 'PATCH', 
                            headers: { 'apikey': SPMB_SUPA_KEY, 'Authorization': 'Bearer ' + SPMB_SUPA_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, 
                            body: JSON.stringify({ status: t })
                        });

                        setTimeout(()=>window.showToast('TIMERS_UPDATED_TO_CLOUD'), 500);
                    }
                });
            });
        };

        window.settingKepsekSPMB = () => {
            fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=in.(kepala_sekolah,nip_kepsek)&select=nama_setting,status', { headers: SPMB_HEAD })
            .then(r=>r.json()).then(data=>{
                let nama='', nip='';
                data.forEach(d=>{ if(d.nama_setting==='kepala_sekolah') nama=d.status; if(d.nama_setting==='nip_kepsek') nip=d.status; });
                Swal.fire({
                    title: 'UPDATE PRINCIPAL DATA',
                    html: `<input id="swal-kepsek" class="swal2-input" placeholder="NAMA KEPSEK" value="${nama}" style="background:#000;color:var(--hud-primary);font-family:Orbitron; border:1px solid var(--hud-primary);"/>
                           <input id="swal-nip" class="swal2-input" placeholder="NIP KEPSEK" value="${nip}" style="background:#000;color:var(--hud-primary);font-family:Orbitron; border:1px solid var(--hud-primary);"/>`,
                    background: '#00141e', color: '#00ffaa',
                    showCancelButton: true, confirmButtonText: 'SAVE_CONFIG', cancelButtonText: 'ABORT',
                    confirmButtonColor: '#00e5ff', cancelButtonColor: '#ff0055'
                }).then(r=>{
                    if(r.isConfirmed){
                        const nm = document.getElementById('swal-kepsek').value;
                        const np = document.getElementById('swal-nip').value;
                        fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=eq.kepala_sekolah', {
                            method: 'PATCH', headers: { 'apikey': SPMB_SUPA_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: nm })
                        });
                        fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=eq.nip_kepsek', {
                            method: 'PATCH', headers: { 'apikey': SPMB_SUPA_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: np })
                        });
                        setTimeout(()=>window.showToast('CONFIG_SAVED'), 500);
