        window.exportExcelSPMB = () => {
            if (spmbDataCache.length === 0) { window.showToast('NO_DATA_TO_EXPORT'); return; }
            const header = [
                'No', 'Nama Lengkap', 'NIPD', 'Jenis Kelamin', 'NISN', 'Tempat Lahir', 'Tanggal Lahir', 'NIK', 'Agama', 
                'Kebutuhan Khusus', 'Anak Ke-', 'Alamat Jalan', 'RT', 'RW', 'Dusun', 'Kelurahan', 'Kecamatan', 'Kode Pos', 
                'Jenis Tinggal', 'Alat Transportasi', 'Lintang', 'Bujur', 'Jarak Sekolah (Km)', 'Telepon', 'No Handphone', 
                'Email', 'Berat Badan (Kg)', 'Tinggi Badan (Cm)', 'Lingkar Kepala (Cm)', 'Jml Saudara', 'No KK', 'No Akta Lahir', 
                'Penerima KPS', 'No KPS', 'Penerima KIP', 'No KIP', 'Nama di KIP', 'No KKS', 'Layak PIP', 'Alasan Layak PIP', 
                'Bank', 'No Rekening', 'Atas Nama Rekening', 'Nama Ayah', 'Tahun Lahir Ayah', 'Pendidikan Ayah', 'Pekerjaan Ayah', 'Penghasilan Ayah', 'NIK Ayah', 
                'Nama Ibu Kandung', 'Tahun Lahir Ibu', 'Pendidikan Ibu', 'Pekerjaan Ibu', 'Penghasilan Ibu', 'NIK Ibu', 
                'Nama Wali', 'Tahun Lahir Wali', 'Pendidikan Wali', 'Pekerjaan Wali', 'Penghasilan Wali', 'NIK Wali', 
                'Asal Sekolah', 'Rombel', 'SKHUN', 'No Peserta UN', 'No Seri Ijazah', 'Status Pendaftaran', 'Tanggal Daftar'
            ];
            const rows = spmbDataCache.map((d, i) => [
                i+1, 
                d.nama||'-', d.nipd||'-', d.jk==='L'?'Laki-laki':(d.jk==='P'?'Perempuan':(d.jk||'-')), d.nisn||'-', d.tempat_lahir||'-', d.tanggal_lahir||'-', d.nik||'-', d.agama||'-', 
                d.kebutuhan_khusus||'-', d.anak_ke||'-', d.alamat||'-', d.rt||'-', d.rw||'-', d.dusun||'-', d.kelurahan||'-', d.kecamatan||'-', d.kode_pos||'-', 
                d.jenis_tinggal||'-', d.alat_transportasi||'-', d.lintang||'-', d.bujur||'-', d.jarak_sekolah||'-', d.telepon||'-', d.hp||'-', 
                d.email||'-', d.berat_badan||'-', d.tinggi_badan||'-', d.lingkar_kepala||'-', d.jml_saudara||'-', d.no_kk||'-', d.no_akta||'-', 
                d.penerima_kps||'-', d.no_kps||'-', d.penerima_kip||'-', d.no_kip||'-', d.nama_kip||'-', d.no_kks||'-', d.layak_pip||'-', d.alasan_pip||'-', 
                d.bank||'-', d.no_rekening||'-', d.atas_nama_rekening||'-', d.nama_ayah||'-', d.tahun_lahir_ayah||'-', d.pendidikan_ayah||'-', d.pekerjaan_ayah||'-', d.penghasilan_ayah||'-', d.nik_ayah||'-', 
                d.nama_ibu||'-', d.tahun_lahir_ibu||'-', d.pendidikan_ibu||'-', d.pekerjaan_ibu||'-', d.penghasilan_ibu||'-', d.nik_ibu||'-', 
                d.nama_wali||'-', d.tahun_lahir_wali||'-', d.pendidikan_wali||'-', d.pekerjaan_wali||'-', d.penghasilan_wali||'-', d.nik_wali||'-', 
                d.sekolah_asal||'-', d.rombel||'-', d.skhun||'-', d.no_peserta_un||'-', d.no_seri_ijazah||'-', d.status_pendaftaran||'-', d.created_at ? new Date(d.created_at).toLocaleDateString('id-ID') : '-'
            ]);
            const ws = XLSX.utils.aoa_to_sheet([header, ...rows]);
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, "Pendaftar");
            XLSX.writeFile(wb, 'SPMB_DATA_' + new Date().toISOString().slice(0,10) + '.xlsx');
            window.showToast('EXCEL_EXPORTED');
        };

        window.cetakBuktiLulusSPMB = (id) => {
            const d = spmbDataCache.find(p => p.id === id);
            if (!d) return;
            window.generatePrintBuktiLulusSPMB([d]);
        };

        window.cetakSemuaBuktiLulusSPMB = () => {
            if (spmbDataCache.length === 0) { window.showToast('NO_DATA_TO_PRINT'); return; }
            window.generatePrintBuktiLulusSPMB(spmbDataCache);
        };

        window.generatePrintBuktiLulusSPMB = (dataList) => {
            let html = '';

            dataList.forEach((d, index) => {
                const pageBreak = index < dataList.length - 1 ? 'page-break-after: always;' : '';
                const strId = (d.id || "0").toString().padStart(3, '0');
                const noReg = "CBD02-26-" + strId;
                const verifyUrl = encodeURIComponent(`https://spmb.sdn02cibadak.sch.id/?v=${d.id}`);
                const valJK = (d.jk || "").toString().toLowerCase();
                const bgMap = valJK.includes("p") ? "#fce7f3" : "#dbeafe"; 
                const txtMap = valJK.includes("p") ? "#9d174d" : "#1e40af"; 
                const labelMap = valJK.includes("p") ? "MERAH (Perempuan)" : "BIRU (Laki-laki)";
                const namaAnanda = d.nama || '-';

                html += `
                <div style="font-family: Arial, sans-serif; color:black; width:100%; max-width:10cm; margin:0 auto; padding:15px; border:2px dashed #000; box-sizing:border-box; position:relative; ${pageBreak}">
                    <div style="text-align:center; border-bottom:3px double #000; padding-bottom:10px; margin-bottom:15px;">
                      <h2 style="margin:0; font-size:16px;">PANITIA SPMB ONLINE 2026</h2>
                      <p style="margin:0; font-size:11px;">SDN 02 CIBADAK - Kab. Sukabumi</p>
                    </div>

                    <h3 style="text-align:center; font-size:14px; text-decoration:underline; margin-bottom:15px;">BUKTI KELULUSAN SELEKSI</h3>

                    <div style="text-align:center; margin-bottom:15px;">
                      <div style="margin-bottom:8px;">
                        <span style="font-size:10px; color:#666;">NAMA LENGKAP:</span>
                        <b style="font-size:15px; text-transform:uppercase; display:block;">${namaAnanda}</b>
                      </div>
                      <div style="margin-bottom:12px;">
                        <span style="font-size:10px; color:#666;">NOMOR REGISTRASI:</span>
                        <b style="font-size:18px; display:block; color:#11ba82;">#${noReg}</b>
                      </div>

                      <div style="text-align:left; border:1px solid #000; padding:10px; font-size:10px; line-height:1.5; background:#fff;">
                        <b style="display:block; border-bottom:1px solid #000; margin-bottom:8px; font-size:11px; background:${bgMap}; color:${txtMap}; padding:2px 5px;">
                          CHECKLIST BERKAS (MAP ${labelMap}):
                        </b>

                        <div style="display: flex; align-items: flex-start; gap: 8px; margin-bottom: 4px;">
                          <div style="min-width: 12px; height: 12px; border: 1px solid #000; margin-top: 2px;"></div>
                          <span>Membawa <b>Materai 10.000</b> (2 Lembar)</span>
                        </div>

                        <div style="display: flex; align-items: flex-start; gap: 8px; margin-bottom: 4px;">
                          <div style="min-width: 12px; height: 12px; border: 1px solid #000; margin-top: 2px;"></div>
                          <span>FC KK & Akta Kelahiran (2 Lembar) <b>+ Tunjukkan ASLI</b></span>
                        </div>

                        <div style="display: flex; align-items: flex-start; gap: 8px; margin-bottom: 4px;">
                          <div style="min-width: 12px; height: 12px; border: 1px solid #000; margin-top: 2px;"></div>
                          <span>Fotocopy KTP Orang Tua (Ayah & Ibu)</span>
                        </div>

                        <div style="display: flex; align-items: flex-start; gap: 8px; margin-bottom: 5px;">
                          <div style="min-width: 12px; height: 12px; border: 1px solid #000; margin-top: 2px;"></div>
                          <span><b>Formulir S1:</b> Akan dicetakan oleh Panitia saat daftar ulang.</span>
                        </div>

                        <i style="font-size:9px; color:#ef4444; border-top:1px solid #eee; padding-top:5px; display:block;">*Panitia akan menceklis kotak di atas saat verifikasi berkas asli.</i>
                      </div>
                    </div>

                    <div style="margin-top:10px; font-size:9px; text-align:center; color:#666;">
                      Dicetak pada: ${new Date().toLocaleDateString('id-ID')} oleh Panitia SPMB SDN 02 Cibadak
                    </div>

                    <div class="qr-signature" style="display:flex; justify-content:space-between; align-items:flex-end; margin-top:15px;">
                      <img src="https://api.qrserver.com/v1/create-qr-code/?size=65x65&data=${verifyUrl}" width="65">
                      <div style="text-align:center; width:150px;">
                        <p style="font-size:10px; margin-bottom:35px;">Ketua Panitia SPMB,</p>
                        <p style="font-weight:bold; font-size:11px; text-decoration:underline;">( SDN 02 CIBADAK )</p>
                      </div>
                    </div>
                </div>`;
            });

            const printWindow = window.open('', '_blank');
            if(!printWindow) {
                window.showToast("POP-UP DIBLOKIR BROWSER! Izinkan pop-up untuk mencetak.", "error");
                return;
            }

            const titleStr = dataList.length > 1 ? "Cetak Massal Bukti Lulus" : `Cetak Bukti Lulus - ${dataList[0].nama || '-'}`;

            printWindow.document.write(`
