        window.cetakS1SPMB = (id) => {
            const d = spmbDataCache.find(p => p.id === id);
            if (!d) return;
            window.loadKepsekAndPrintSPMB([d]);
        };

        window.cetakSemuaS1 = () => {
            if (spmbDataCache.length === 0) { window.showToast('NO_DATA_TO_PRINT'); return; }
            window.loadKepsekAndPrintSPMB(spmbDataCache);
        };

        window.loadKepsekAndPrintSPMB = (dataList) => {
            fetch(SPMB_SUPA_URL + '/rest/v1/pengaturan?nama_setting=in.(kepala_sekolah,nip_kepsek)&select=nama_setting,status', { headers: { 'apikey': SPMB_SUPA_KEY } })
            .then(r=>r.json()).then(data=>{
                let kepsek = '-', nip = '-';
                data.forEach(d=>{ if(d.nama_setting==='kepala_sekolah') kepsek = d.status||'-'; if(d.nama_setting==='nip_kepsek') nip = d.status||'-'; });
                window.generatePrintS1SPMB(dataList, kepsek, nip);
            }).catch(() => window.generatePrintS1SPMB(dataList, '-', '-'));
        };

        // --- FUNGSI CETAK S1 (FONT FORMAL & MATERAI LANDSCAPE) ---
        window.generatePrintS1SPMB = (dataList, kepsek, nipKepsek) => {
            let html = '';
            const tahunAjar = `${new Date().getFullYear()} / ${new Date().getFullYear() + 1}`;

            dataList.forEach((d, index) => {
                const pageBreak = index < dataList.length - 1 ? 'page-break-after: always;' : '';
                const strId = (d.id || "0").toString().padStart(3, '0');
                const noReg = "CBD02-26-" + strId;

                // --- GENERATE QR VERIFICATION ---
                const verifyUrl = encodeURIComponent(`https://spmb.sdn02cibadak.sch.id/?v=${d.id}`);
                const qrImg = `https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${verifyUrl}&margin=0`;

                html += `
                <div style="background:#fff; color:#000; width:100%; max-width:210mm; min-height:297mm; margin:0 auto; padding:0; box-sizing:border-box; position:relative; ${pageBreak}">

                    <!-- 1. KOP SURAT GAMBAR FULL -->
                    <div style="text-align:center; margin-bottom:15px;">
                        <img src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgHJHdzvsrvzHVMFsAmI_Ra_4vlYn39plogGMmNIUO7MV71T8zT9YWUFQyO5UD6oeSQ7jew1exTAXcI24JwK3eBiokcmNppHqGjvq70RTfjeYdZAhIahHq0D8m2Jrixl_8bb6BaFGhm0xpov4cojZ_ydeyOtE1xM7wrxn7FSMy0EP5KTuyqWVscaIkCyN3T/s955/KOP%20Baru.png" style="width:100%; display:block; margin:0 auto;" alt="KOP Surat"/>
                    </div>

                    <!-- 2. JUDUL FORMULIR -->
                    <div style="text-align:center; margin-bottom:15px;">
                        <div style="font-size:14pt; font-weight:bold; text-decoration:underline;">FORMULIR PENDAFTARAN PESERTA DIDIK BARU (F-PD)</div>
                        <div style="font-size:11pt; font-weight:bold; margin-bottom:8px;">TAHUN PELAJARAN ${tahunAjar}</div>
                        <div style="display:inline-block; border:2px solid #000; padding:4px 15px; font-weight:bold; font-size:12pt; letter-spacing:1px;">
                            NO. REG: #${noReg}
                        </div>
                    </div>

                    <!-- 3. TABEL DATA PRIBADI SISWA -->
                    <div style="font-weight:bold; font-size:12pt; margin-bottom:5px; background:#e0e0e0; padding:5px 10px; border:1px solid #000;">A. DATA PRIBADI CALON PESERTA DIDIK</div>
                    <table style="width:100%; border-collapse:collapse; font-size:11pt; margin-bottom:15px; color:#000;">
                        <tr><td style="width:35%; border:1px solid #000; padding:5px 8px;">1. Nama Lengkap</td><td style="border:1px solid #000; padding:5px 8px; text-transform:uppercase; font-weight:bold;">${d.nama || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">2. Jenis Kelamin</td><td style="border:1px solid #000; padding:5px 8px;">${d.jk === 'L' ? 'Laki-laki (L)' : d.jk === 'P' ? 'Perempuan (P)' : (d.jk || '-')}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">3. NISN</td><td style="border:1px solid #000; padding:5px 8px;">${d.nisn || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">4. Nomor Induk Kependudukan (NIK)</td><td style="border:1px solid #000; padding:5px 8px; font-weight:bold;">${d.nik || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">5. Tempat Lahir</td><td style="border:1px solid #000; padding:5px 8px;">${d.tempat_lahir || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">6. Tanggal Lahir</td><td style="border:1px solid #000; padding:5px 8px;">${d.tanggal_lahir || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">7. No. Registrasi Akta Lahir</td><td style="border:1px solid #000; padding:5px 8px;">${d.no_akta || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">8. Agama & Kepercayaan</td><td style="border:1px solid #000; padding:5px 8px;">${d.agama || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">9. Anak Ke -</td><td style="border:1px solid #000; padding:5px 8px;">${d.anak_ke || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">10. Alamat Jalan</td><td style="border:1px solid #000; padding:5px 8px;">${d.alamat || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">11. RT</td><td style="border:1px solid #000; padding:5px 8px;">${d.rt || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">12. RW</td><td style="border:1px solid #000; padding:5px 8px;">${d.rw || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">13. Nama Kelurahan / Desa</td><td style="border:1px solid #000; padding:5px 8px;">${d.kelurahan || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">14. Kecamatan</td><td style="border:1px solid #000; padding:5px 8px;">${d.kecamatan || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">15. Kode Pos</td><td style="border:1px solid #000; padding:5px 8px;">${d.kode_pos || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">16. No. Handphone (WA)</td><td style="border:1px solid #000; padding:5px 8px;">${d.hp || '-'}</td></tr>
                    </table>

                    <!-- 4. TABEL DATA AYAH KANDUNG -->
                    <div style="font-weight:bold; font-size:12pt; margin-bottom:5px; background:#e0e0e0; padding:5px 10px; border:1px solid #000;">B. DATA AYAH KANDUNG</div>
                    <table style="width:100%; border-collapse:collapse; font-size:11pt; margin-bottom:15px; color:#000;">
                        <tr><td style="width:35%; border:1px solid #000; padding:5px 8px;">17. Nama Ayah Kandung</td><td style="border:1px solid #000; padding:5px 8px;">${d.nama_ayah || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">18. NIK Ayah</td><td style="border:1px solid #000; padding:5px 8px;">${d.nik_ayah || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">19. Pekerjaan Ayah</td><td style="border:1px solid #000; padding:5px 8px;">${d.pekerjaan_ayah || '-'}</td></tr>
                    </table>

                    <!-- 5. TABEL DATA IBU KANDUNG -->
                    <div style="font-weight:bold; font-size:12pt; margin-bottom:5px; background:#e0e0e0; padding:5px 10px; border:1px solid #000;">C. DATA IBU KANDUNG</div>
                    <table style="width:100%; border-collapse:collapse; font-size:11pt; margin-bottom:15px; color:#000;">
                        <tr><td style="width:35%; border:1px solid #000; padding:5px 8px;">20. Nama Ibu Kandung</td><td style="border:1px solid #000; padding:5px 8px;">${d.nama_ibu || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">21. NIK Ibu</td><td style="border:1px solid #000; padding:5px 8px;">${d.nik_ibu || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">22. Pekerjaan Ibu</td><td style="border:1px solid #000; padding:5px 8px;">${d.pekerjaan_ibu || '-'}</td></tr>
                    </table>

                    <!-- 6. TABEL DOKUMEN & ASAL SEKOLAH -->
                    <div style="font-weight:bold; font-size:12pt; margin-bottom:5px; background:#e0e0e0; padding:5px 10px; border:1px solid #000;">D. DATA LAINNYA</div>
                    <table style="width:100%; border-collapse:collapse; font-size:11pt; margin-bottom:20px; color:#000;">
                        <tr><td style="width:35%; border:1px solid #000; padding:5px 8px;">23. No. Kartu Keluarga (KK)</td><td style="border:1px solid #000; padding:5px 8px;">${d.no_kk || '-'}</td></tr>
                        <tr><td style="border:1px solid #000; padding:5px 8px;">24. Asal Sekolah (TK/PAUD)</td><td style="border:1px solid #000; padding:5px 8px;">${d.sekolah_asal || '-'}</td></tr>
                    </table>

                    <!-- 6. PERNYATAAN -->
                    <div style="font-size:11pt; text-align:justify; margin-bottom:30px; line-height:1.5;">
                        Demikian formulir ini diisi dengan data yang sebenar-benarnya sesuai dengan dokumen kependudukan yang sah. Apabila di kemudian hari terdapat ketidaksesuaian data, kami selaku orang tua/wali bersedia menerima konsekuensi sesuai dengan peraturan yang berlaku di instansi pendidikan terkait.
                    </div>

                    <!-- 7. TANDA TANGAN & MATERAI -->
                    <table style="width:100%; font-size:11pt; margin-top:30px; page-break-inside: avoid; border:none; color:#000;">
                        <tr>
                            <!-- KIRI: KEPALA SEKOLAH -->
                            <td style="width:50%; text-align:center; vertical-align:top; border:none; padding: 0 20px;">
                                <div style="margin-bottom: 110px;">
                                    Mengetahui,<br>
                                    Kepala SDN 02 Cibadak
                                </div>
                                <div>
                                    ${kepsek !== '-' 
                                        ? `<b><u>${kepsek}</u></b><br>NIP. ${nipKepsek}` 
                                        : `<b>( ................................................... )</b><br>NIP. ..........................................`
                                    }
                                </div>
                            </td>

                            <!-- KANAN: ORANG TUA / WALI -->
                            <td style="width:50%; text-align:center; vertical-align:top; border:none; padding: 0 20px;">
                                <div style="margin-bottom: 30px;">
                                    Cibadak, ........................ ${new Date().getFullYear()}<br>
                                    Orang Tua / Wali Calon Siswa
                                </div>

                                <!-- BOX MATERAI (Landscape, Center) -->
                                <div style="margin: 0 auto 30px auto; border:1px dashed #000; width:80px; height:50px; display:flex; flex-direction:column; align-items:center; justify-content:center; font-size:8pt; color:#000;">
                                    <span>Materai</span>
                                    <span>10.000</span>
                                </div>

                                <div>
                                    <b>( ................................................... )</b><br>
                                    <span style="font-size:10pt;">Tanda Tangan & Nama Jelas</span>
                                </div>
                            </td>
                        </tr>
                    </table>

                    <!-- 8. KOTAK VERIFIKASI PANITIA & QR CODE -->
                    <table style="width:100%; margin-top:20px; border:2px dashed #000; background:#f9f9f9; color:#000; border-collapse:collapse; page-break-inside:avoid;">
                        <tr>
                            <td style="padding:12px; font-size:10pt; vertical-align:top; width:80%;">
                                <b>[ BAGIAN PANITIA SPMB ]</b><br>
                                Telah diperiksa dengan dokumen asli (KK/Akta/KTP) oleh Panitia pada tanggal: ..................................<br><br>
                                <span style="display:inline-block; border:1px solid #000; width:12px; height:12px; margin-right:5px; background:#fff;"></span> <b>SESUAI</b>
                                <span style="display:inline-block; width:30px;"></span>
                                <span style="display:inline-block; border:1px solid #000; width:12px; height:12px; margin-right:5px; background:#fff;"></span> <b>TIDAK SESUAI</b>
                                <br><br>
                                Paraf Petugas Verifikasi: .........................
                            </td>
                            <td style="padding:12px; text-align:center; vertical-align:middle; width:20%; border-left:2px dashed #000; background:#fff;">
                                <img src="${qrImg}" style="width:75px; height:75px; border:1px solid #000; padding:2px; display:block; margin:0 auto;" alt="QR Code"/>
                                <div style="font-size:8pt; font-weight:bold; margin-top:5px;">SCAN VERIFIKASI</div>
                            </td>
                        </tr>
                    </table>

                </div>`;
            });

            const printWindow = window.open('', '_blank');
            if(!printWindow) {
                window.showToast("POP-UP DIBLOKIR BROWSER! Izinkan pop-up untuk mencetak.", "error");
                return;
            }

            printWindow.document.write(`
                <!DOCTYPE html>
                <html>
                <head>
                    <title>Cetak S1 - SDN 02 CIBADAK</title>
                    <style>
                        /* PAKSA FONT FORMAL UNTUK SELURUH HALAMAN PRINT */
                        * { font-family: 'Times New Roman', Times, serif !important; }
                        body { background-color: #fff; margin: 0; padding: 0; color: #000; }
                        table { border-collapse: collapse; }
                        @page { size: A4 portrait; margin: 15mm; }
                    </style>
                </head>
                <body>
                    ${html}
                    <script>
                        window.onload = function() {
                            setTimeout(function() {
                                window.print();
                                window.onafterprint = function() { window.close(); }
                            }, 500);
                        };
                    <\/script>
                </body>
                </html>
            `);

            printWindow.document.close();
        };

/**/
